  "Cheese wheel": "B\xE1nh ph\xF4 mai",
  "Pancakes": "B\xE1nh k\u1EBFp",
  "Laid by your chickens. Sell it, or cook an omelette or pancakes at the kitchen.": "Tr\u1EE9ng do g\xE0 trong v\u01B0\u1EDDn \u0111\u1EBB. B\xE1n ho\u1EB7c d\xF9ng \u0111\u1EC3 l\xE0m tr\u1EE9ng cu\u1ED9n v\xE0 b\xE1nh k\u1EBFp t\u1EA1i b\u1EBFp.",
  "From your cows. Sell it, or make a milkshake, cheese or pancakes at the kitchen.": "S\u1EEFa t\u1EEB b\xF2 trong v\u01B0\u1EDDn. B\xE1n ho\u1EB7c d\xF9ng \u0111\u1EC3 l\xE0m s\u1EEFa l\u1EAFc, ph\xF4 mai v\xE0 b\xE1nh k\u1EBFp t\u1EA1i b\u1EBFp.",
  "Two eggs, folded warm. Heals 40 and +10 defense for 90s.": "Hai qu\u1EA3 tr\u1EE9ng cu\u1ED9n n\xF3ng h\u1ED5i. H\u1ED3i 40 m\xE1u v\xE0 t\u0103ng 10 gi\xE1p trong 90 gi\xE2y.",
  "Cold and frothy. Heals 45 and +25% speed for 90s.": "M\xE1t l\u1EA1nh v\xE0 b\xF4ng x\u1ED1p. H\u1ED3i 45 m\xE1u v\xE0 t\u0103ng 25% t\u1ED1c \u0111\u1ED9 trong 90 gi\xE2y.",
  "Three jugs of milk, aged a little. Heals 70 and +3 HP/s for 120s.": "\u1EE6 t\u1EEB ba b\xECnh s\u1EEFa. H\u1ED3i 70 m\xE1u v\xE0 h\u1ED3i th\xEAm 3 m\xE1u/gi\xE2y trong 120 gi\xE2y.",
  "An egg and a jug of milk. Heals 55 and +30% XP for 120s.": "L\xE0m t\u1EEB m\u1ED9t qu\u1EA3 tr\u1EE9ng v\xE0 m\u1ED9t b\xECnh s\u1EEFa. H\u1ED3i 55 m\xE1u v\xE0 t\u0103ng 30% kinh nghi\u1EC7m nh\u1EADn \u0111\u01B0\u1EE3c trong 120 gi\xE2y.",
  "A keepsake material from the first garden. Can still be sold.": "Nguy\xEAn li\u1EC7u k\u1EF7 ni\u1EC7m t\u1EEB khu v\u01B0\u1EDDn \u0111\u1EA7u ti\xEAn. V\u1EABn c\xF3 th\u1EC3 b\xE1n.",
  "Your original companion stays with you.": "Ng\u01B0\u1EDDi b\u1EA1n \u0111\u1ED3ng h\xE0nh \u0111\u1EA7u ti\xEAn v\u1EABn lu\xF4n b\xEAn b\u1EA1n.",
  "Cooked at home. Stronger healing and longer effects.": "N\u1EA5u \u1EDF nh\xE0. H\u1ED3i nhi\u1EC1u m\xE1u h\u01A1n v\xE0 hi\u1EC7u \u1EE9ng k\xE9o d\xE0i h\u01A1n.",
  "One more garden bed for home. Place it from your backpack, or tap a garden bed and choose \u2795 Expand garden.": "Th\xEAm m\u1ED9t lu\u1ED1ng \u0111\u1EA5t cho v\u01B0\u1EDDn nh\xE0. \u0110\u1EB7t t\u1EEB ba l\xF4 ho\u1EB7c ch\u1EA1m v\xE0o m\u1ED9t lu\u1ED1ng \u0111\u1EA5t r\u1ED3i ch\u1ECDn \u2795 M\u1EDF r\u1ED9ng v\u01B0\u1EDDn.",
  "Removes half of the crop's original growing time. Two uses ripen a newly planted crop.": "Gi\u1EA3m th\u1EDDi gian ch\u1EDD b\u1EB1ng m\u1ED9t n\u1EEDa th\u1EDDi gian sinh tr\u01B0\u1EDFng ban \u0111\u1EA7u c\u1EE7a c\xE2y. D\xF9ng hai l\u1EA7n s\u1EBD l\xE0m c\xE2y v\u1EEBa tr\u1ED3ng ch\xEDn ngay.",
  "Equip this rod and visit a pond. Hook at the bite, then balance reeling with line tension.": "Trang b\u1ECB c\u1EA7n r\u1ED3i \u0111\u1EBFn ao. Gi\u1EADt c\u1EA7n khi c\xE1 c\u1EAFn c\xE2u, sau \u0111\xF3 v\u1EEBa thu d\xE2y v\u1EEBa gi\u1EEF \u0111\u1ED9 c\u0103ng ph\xF9 h\u1EE3p.",
  "A stronger rod that makes difficult fish easier to land and improves rare catches. A strained line snaps only 30% of the time.": "C\u1EA7n c\xE2u kh\u1ECFe h\u01A1n, gi\xFAp k\xE9o c\xE1 l\u1EDBn d\u1EC5 h\u01A1n v\xE0 t\u0103ng c\u01A1 h\u1ED9i c\xE2u \u0111\u01B0\u1EE3c c\xE1 hi\u1EBFm. Khi d\xE2y b\u1ECB c\u0103ng, ch\u1EC9 30% s\u1ED1 l\u1EA7n l\xE0 \u0111\u1EE9t.",
  "Your garden and four trails: forest, meadow, swamp and canyon.": "V\u01B0\u1EDDn nh\xE0 v\xE0 b\u1ED1n l\u1ED1i \u0111i: r\u1EEBng, \u0111\u1ED3ng c\u1ECF, \u0111\u1EA7m l\u1EA7y v\xE0 h\u1EBBm n\xFAi.",
  "Sweet forests, springy surprises and powerful candy creatures.": "Nh\u1EEFng khu r\u1EEBng ng\u1ECDt ng\xE0o, b\u1EA5t ng\u1EDD n\u1EA3y t\u01B0ng v\xE0 sinh v\u1EADt k\u1EB9o \u0111\u1EA7y s\u1EE9c m\u1EA1nh.",
  "Slippery ice, frozen ponds and snowbound bosses. Plan your stopping distance.": "M\u1EB7t b\u0103ng tr\u01A1n tr\u01B0\u1EE3t, ao \u0111\xF3ng b\u0103ng v\xE0 tr\xF9m tuy\u1EBFt. H\xE3y t\xEDnh tr\u01B0\u1EDBc kho\u1EA3ng c\xE1ch d\u1EEBng l\u1EA1i.",
  "Eruptions, rising lava, meteors and a hidden cave furnace. Watch the warning circles.": "N\xFAi l\u1EEDa phun tr\xE0o, dung nham d\xE2ng, thi\xEAn th\u1EA1ch v\xE0 l\xF2 r\xE8n \u1EA9n trong hang. H\xE3y ch\xFA \xFD c\xE1c v\xF2ng c\u1EA3nh b\xE1o.",
  "Ride the moving trains and open surprise gifts among giant toys.": "L\xEAn t\xE0u \u0111ang ch\u1EA1y v\xE0 m\u1EDF qu\xE0 b\u1EA5t ng\u1EDD gi\u1EEFa nh\u1EEFng m\xF3n \u0111\u1ED3 ch\u01A1i kh\u1ED5ng l\u1ED3.",
  "Changing thorn walls, poisonous plants and restorative fruit.": "T\u01B0\u1EDDng gai thay \u0111\u1ED5i, c\xE2y c\xF3 \u0111\u1ED9c v\xE0 tr\xE1i c\xE2y h\u1ED3i ph\u1EE5c.",
  "Swim between islands. Refill your air at bubbles or ride a sea turtle.": "B\u01A1i gi\u1EEFa c\xE1c \u0111\u1EA3o. L\u1EA5y th\xEAm kh\xF4ng kh\xED t\u1EA1i bong b\xF3ng ho\u1EB7c c\u01B0\u1EE1i r\xF9a bi\u1EC3n.",
  "Bounce between floating islands and watch the wind near their edges.": "Nh\u1EA3y gi\u1EEFa c\xE1c \u0111\u1EA3o n\u1ED5i v\xE0 c\u1EA9n th\u1EADn v\u1EDBi gi\xF3 \u1EDF r\xECa \u0111\u1EA3o.",
  "Explore the darkness, light ancient pillars and face the Night Lord.": "Kh\xE1m ph\xE1 b\xF3ng t\u1ED1i, th\u1EAFp s\xE1ng c\xE1c tr\u1EE5 c\u1ED5 v\xE0 \u0111\u1ED1i m\u1EB7t v\u1EDBi Ch\xFAa T\u1EC3 B\xF3ng \u0110\xEAm.",
  "Weapons": "V\u0169 kh\xED",
  "Equipment": "Trang b\u1ECB",
