  "Livestock produces while you are away and leaves meat after two real hours. Your guard dog waits by the pen at home, trots after you in the wilds and on other planets, and guards the garden either way.": "Gia s\xFAc, gia c\u1EA7m v\u1EABn cho s\u1EA3n ph\u1EA9m khi b\u1EA1n v\u1EAFng m\u1EB7t v\xE0 \u0111\u1EC3 l\u1EA1i th\u1ECBt sau hai gi\u1EDD th\u1EF1c. Ch\xF3 canh ch\u1EDD b\xEAn chu\u1ED3ng khi b\u1EA1n \u1EDF nh\xE0, ch\u1EA1y theo b\u1EA1n ngo\xE0i v\xF9ng hoang d\xE3 v\xE0 tr\xEAn c\xE1c h\xE0nh tinh kh\xE1c, v\xE0 lu\xF4n canh gi\u1EEF khu v\u01B0\u1EDDn.",
  "The farm is empty. Choose a new friend below.": "Trang tr\u1EA1i \u0111ang tr\u1ED1ng. Ch\u1ECDn m\u1ED9t ng\u01B0\u1EDDi b\u1EA1n m\u1EDBi b\xEAn d\u01B0\u1EDBi.",
  "Protects ripe crops from theft. No feeding, products or lifespan limit.": "B\u1EA3o v\u1EC7 c\xE2y ch\xEDn kh\u1ECFi tr\u1ED9m. Kh\xF4ng c\u1EA7n cho \u0103n, kh\xF4ng t\u1EA1o s\u1EA3n ph\u1EA9m v\xE0 kh\xF4ng gi\u1EDBi h\u1EA1n tu\u1ED5i th\u1ECD.",
