  "Stores 5 products instead of 3; production takes 70% of the normal time.": "T\xEDch tr\u1EEF 5 s\u1EA3n ph\u1EA9m thay v\xEC 3; th\u1EDDi gian s\u1EA3n xu\u1EA5t c\xF2n 70% so v\u1EDBi b\xECnh th\u01B0\u1EDDng.",
