  "A heavy reusable throwing fork: +100 attack in fights, and the tool for hunting pond fish, large forest birds and the rare Lake Guardian. No ammunition needed.": "Lao ba ch\u0129a n\u1EB7ng, d\xF9ng nhi\u1EC1u l\u1EA7n: +100 t\u1EA5n c\xF4ng khi chi\u1EBFn \u0111\u1EA5u, v\xE0 l\xE0 c\xF4ng c\u1EE5 s\u0103n c\xE1 trong ao, chim l\u1EDBn trong r\u1EEBng v\xE0 C\xE1 Th\u1EA7n H\u1ED3 hi\u1EBFm c\xF3. Kh\xF4ng c\u1EA7n \u0111\u1EA1n.",
