  "Use a rod from your backpack for line fishing.": "Trang b\u1ECB c\u1EA7n c\xE2u t\u1EEB t\xFAi \u0111\u1ED3 \u0111\u1EC3 c\xE2u b\u1EB1ng d\xE2y.",
  "Finish your cast and return to your own shore before hunting fish.": "H\xE3y thu c\u1EA7n c\xE2u v\xE0 tr\u1EDF v\u1EC1 b\u1EDD ao c\u1EE7a m\xECnh tr\u01B0\u1EDBc khi s\u0103n c\xE1.",
  "Equip your hunting harpoon and aim at an available nearby fish.": "H\xE3y trang b\u1ECB lao s\u0103n v\xE0 nh\u1EAFm v\xE0o m\u1ED9t con c\xE1 g\u1EA7n \u0111\xF3 ch\u01B0a b\u1ECB b\u1EAFt.",
