  "Harvests ripe beds and replants them from your seeds, like the garden robot. Both can work: a bed is only ever harvested once.": "Thu ho\u1EA1ch lu\u1ED1ng ch\xEDn v\xE0 gieo l\u1EA1i b\u1EB1ng h\u1EA1t c\u1EE7a b\u1EA1n, nh\u01B0 robot l\xE0m v\u01B0\u1EDDn. C\u1EA3 hai c\xF9ng l\xE0m \u0111\u01B0\u1EE3c: m\u1ED7i lu\u1ED1ng ch\u1EC9 \u0111\u01B0\u1EE3c thu ho\u1EA1ch m\u1ED9t l\u1EA7n.",
  "Collects eggs and milk into your bag and feeds animals from your cheapest crop, always leaving you one.": "Nh\u1EB7t tr\u1EE9ng v\xE0 s\u1EEFa v\xE0o t\xFAi, cho th\xFA \u0103n b\u1EB1ng n\xF4ng s\u1EA3n r\u1EBB nh\u1EA5t c\u1EE7a b\u1EA1n v\xE0 lu\xF4n ch\u1EEBa l\u1EA1i cho b\u1EA1n m\u1ED9t c\xE1i.",
  "Gathers ripe crops and farm products, then cooks half of them (rounded down) at the volcano kitchen. The other half goes to your bag raw.": "Thu gom n\xF4ng s\u1EA3n ch\xEDn v\xE0 s\u1EA3n ph\u1EA9m trang tr\u1EA1i, r\u1ED3i n\u1EA5u m\u1ED9t n\u1EEDa (l\xE0m tr\xF2n xu\u1ED1ng) \u1EDF b\u1EBFp n\xFAi l\u1EEDa. N\u1EEDa c\xF2n l\u1EA1i v\xE0o t\xFAi c\u1EE7a b\u1EA1n \u1EDF d\u1EA1ng s\u1ED1ng.",
  "Back to work": "L\xE0m vi\u1EC7c ti\u1EBFp",
  "{name} \xB7 taking a break indoors": "{name} \xB7 \u0111ang ngh\u1EC9 trong nh\xE0",
  "Ask to work now": "Nh\u1EDD l\xE0m vi\u1EC7c ngay",
  "Ask Bolt to work now": "Nh\u1EDD Bolt l\xE0m vi\u1EC7c ngay",
  "Bolt takes a rest at the end of each day so the grown garden can be seen.": "Cu\u1ED1i m\u1ED7i ng\xE0y Bolt ngh\u1EC9 m\u1ED9t l\xFAc \u0111\u1EC3 m\xECnh ng\u1EAFm v\u01B0\u1EDDn c\xE2y \u0111\xE3 l\u1EDBn.",
  "Welcome to the game!": "Ch\xE0o m\u1EEBng \u0111\u1EBFn v\u1EDBi tr\xF2 ch\u01A1i!",
  "Hi boss! I am Pepper, your cook. Welcome to the game!": "Ch\xE0o s\u1EBFp! Em l\xE0 Pepper, \u0111\u1EA7u b\u1EBFp c\u1EE7a s\u1EBFp. Ch\xE0o m\u1EEBng s\u1EBFp \u0111\u1EBFn v\u1EDBi tr\xF2 ch\u01A1i!",
  "Guess what? You are lucky today! I played the lottery and won 1,000,000 energy. Do you want it?": "S\u1EBFp \u0111o\xE1n xem? H\xF4m nay s\u1EBFp may l\u1EAFm! Em \u0111i x\u1ED5 s\u1ED1 tr\xFAng 1.000.000 n\u0103ng l\u01B0\u1EE3ng. S\u1EBFp c\xF3 mu\u1ED1n nh\u1EADn kh\xF4ng?",
  "Yes, take it!": "C\xF3, nh\u1EADn lu\xF4n!",
  "No, thanks": "Th\xF4i, c\u1EA3m \u01A1n",
  "YOUR COOK": "\u0110\u1EA6U B\u1EBEP C\u1EE6A S\u1EBEP",
  "Pepper joined you, and you start with 1,000,000 energy!": "Pepper \u0111\xE3 gia nh\u1EADp, v\xE0 s\u1EBFp b\u1EAFt \u0111\u1EA7u v\u1EDBi 1.000.000 n\u0103ng l\u01B0\u1EE3ng!",
  "Pepper joined you. A fair start it is!": "Pepper \u0111\xE3 gia nh\u1EADp. Kh\u1EDFi \u0111\u1EA7u c\xF4ng b\u1EB1ng nh\xE9!",
  "Choose a save profile": "Ch\u1ECDn h\u1ED3 s\u01A1 l\u01B0u",
  "Profile": "H\u1ED3 s\u01A1",
  "Level": "C\u1EA5p",
  "New game": "Tr\xF2 ch\u01A1i m\u1EDBi",
  "Full screen": "To\xE0n m\xE0n h\xECnh",
  "Fill the whole screen; press again to leave.": "Ph\u1EE7 k\xEDn m\xE0n h\xECnh; b\u1EA5m l\u1EA7n n\u1EEFa \u0111\u1EC3 tho\xE1t.",
  "Play online with friends": "Ch\u01A1i tr\u1EF1c tuy\u1EBFn c\xF9ng b\u1EA1n b\xE8",
  "{n} online": "{n} \u0111ang online",
  "\xD7{n} size bonus": "Th\u01B0\u1EDFng c\u1EE1 l\u1EDBn \xD7{n}",
  "Take a break": "Ngh\u1EC9 m\u1ED9t l\xE1t",
  "Beat a boss on another planet to open this cage.": "H\xE3y h\u1EA1 m\u1ED9t tr\xF9m \u1EDF h\xE0nh tinh kh\xE1c \u0111\u1EC3 m\u1EDF l\u1ED3ng n\xE0y.",
  "Defeat the {boss} nearby to open this cage.": "H\xE3y h\u1EA1 {boss} g\u1EA7n \u0111\xE2y \u0111\u1EC3 m\u1EDF l\u1ED3ng n\xE0y.",
  "Thank you! I am Sprout.": "C\u1EA3m \u01A1n b\u1EA1n! M\xECnh l\xE0 Sprout.",
  "The treant caught me watering its roots. Now I will tend your garden!": "C\xE2y c\u1ED5 th\u1EE5 b\u1EAFt \u0111\u01B0\u1EE3c m\xECnh t\u01B0\u1EDBi r\u1EC5 n\xF3. Gi\u1EDD m\xECnh s\u1EBD ch\u0103m v\u01B0\u1EDDn cho b\u1EA1n!",
  "You beat the bear! I am Clover.": "B\u1EA1n th\u1EAFng con g\u1EA5u r\u1ED3i! M\xECnh l\xE0 Clover.",
  "It caught me sharing its honey with hens. I will care for your animals!": "N\xF3 b\u1EAFt \u0111\u01B0\u1EE3c m\xECnh chia m\u1EADt c\u1EE7a n\xF3 cho g\xE0. M\xECnh s\u1EBD ch\u0103m \u0111\xE0n th\xFA cho b\u1EA1n!",
  "Free at last! I am Pepper.": "Cu\u1ED1i c\xF9ng c\u0169ng t\u1EF1 do! M\xECnh l\xE0 Pepper.",
  "The robot wanted a cook who never sleeps. I would love to cook for you!": "Con robot mu\u1ED1n m\u1ED9t \u0111\u1EA7u b\u1EBFp kh\xF4ng bao gi\u1EDD ng\u1EE7. M\xECnh r\u1EA5t mu\u1ED1n n\u1EA5u \u0103n cho b\u1EA1n!",
  "{names} reached Clover Village and went to work!": "{names} \u0111\xE3 v\u1EC1 t\u1EDBi H\xE0nh Tinh M\u1EA7m Xanh v\xE0 b\u1EAFt tay v\xE0o vi\u1EC7c!",
  "While you were away, your friends did {count} jobs.": "Trong l\xFAc b\u1EA1n v\u1EAFng m\u1EB7t, c\xE1c b\u1EA1n nh\u1ECF \u0111\xE3 l\xE0m {count} vi\u1EC7c.",
  "While you were out, your helpers stored:": "Trong l\xFAc b\u1EA1n ra ngo\xE0i, c\xE1c b\u1EA1n gi\xFAp vi\u1EC7c \u0111\xE3 c\u1EA5t v\xE0o r\u01B0\u01A1ng:",
  "and {count} more": "v\xE0 {count} lo\u1EA1i kh\xE1c",
