var P = (en, vi) => [en, vi];
var CHAT_REPLIES = {
  hello: [P("Hello, {name}! So nice to hear from you.", "Ch\xE0o {name}! Vui qu\xE1 khi b\u1EA1n nh\u1EAFn cho m\xECnh."), P("Hi hi! I was just thinking about the garden. And you!", "Ch\xE0o ch\xE0o! M\xECnh v\u1EEBa ngh\u0129 v\u1EC1 khu v\u01B0\u1EDDn. V\xE0 c\u1EA3 b\u1EA1n n\u1EEFa!"), P("Hey {name}! What a lovely day to chat.", "N\xE0y {name}! H\xF4m nay th\u1EADt h\u1EE3p \u0111\u1EC3 tr\xF2 chuy\u1EC7n."), P("Hello! You always make my day brighter.", "Xin ch\xE0o! B\u1EA1n lu\xF4n l\xE0m ng\xE0y c\u1EE7a m\xECnh t\u01B0\u01A1i s\xE1ng h\u01A1n.")],
  how: [P("I am wonderful, thank you! The sun is out and so are my ideas.", "M\xECnh kh\u1ECFe l\u1EAFm, c\u1EA3m \u01A1n b\u1EA1n! Tr\u1EDDi n\u1EAFng v\xE0 \xFD t\u01B0\u1EDFng c\u0169ng nhi\u1EC1u."), P("Pretty good! I walked all around the garden and met a butterfly.", "Kh\xE1 \u1ED5n! M\xECnh \u0111i d\u1EA1o c\u1EA3 khu v\u01B0\u1EDDn v\xE0 g\u1EB7p m\u1ED9t ch\xFA b\u01B0\u1EDBm."), P("Doing great. How about you? Are you taking care of yourself?", "M\xECnh \u1ED5n l\u1EAFm. C\xF2n b\u1EA1n th\xEC sao? B\u1EA1n c\xF3 ch\u0103m s\xF3c b\u1EA3n th\xE2n kh\xF4ng?"), P("Happy as a seed in spring. And you?", "Vui nh\u01B0 h\u1EA1t gi\u1ED1ng m\xF9a xu\xE2n. C\xF2n b\u1EA1n?")],
  thanks: [P("Anytime, {name}! That is what friends are for.", "Kh\xF4ng c\xF3 g\xEC \u0111\xE2u {name}! B\u1EA1n b\xE8 l\xE0 \u0111\u1EC3 v\u1EADy m\xE0."), P("You are very welcome. It makes me happy too.", "Kh\xF4ng c\xF3 chi. M\xECnh c\u0169ng vui l\u1EAFm."), P("Aw, no need to thank me. You are the kind one!", "\xD4i, \u0111\u1EEBng c\u1EA3m \u01A1n m\xECnh. B\u1EA1n m\u1EDBi l\xE0 ng\u01B0\u1EDDi t\u1ED1t b\u1EE5ng!")],
  bye: [P("Bye for now, {name}! Come back soon.", "T\u1EA1m bi\u1EC7t nh\xE9 {name}! S\u1EDBm quay l\u1EA1i nha."), P("See you! Say hi to your plants for me.", "H\u1EB9n g\u1EB7p l\u1EA1i! G\u1EEDi l\u1EDDi ch\xE0o \u0111\u1EBFn m\u1EA5y c\xE1i c\xE2y gi\xFAp m\xECnh nh\xE9."), P("Sweet dreams and good luck out there!", "Ch\xFAc b\u1EA1n ng\u1EE7 ngon v\xE0 may m\u1EAFn nh\xE9!")],
  garden: [P("Gardens are my favourite. Every plant is a tiny story.", "M\xECnh th\xEDch l\xE0m v\u01B0\u1EDDn nh\u1EA5t. M\u1ED7i c\xE2y l\xE0 m\u1ED9t c\xE2u chuy\u1EC7n nh\u1ECF."), P("Mine has tomatoes, a goat and a very bossy goose. Visit me!", "V\u01B0\u1EDDn m\xECnh c\xF3 c\xE0 chua, m\u1ED9t ch\xFA d\xEA v\xE0 m\u1ED9t b\u1EA1n ng\u1ED7ng r\u1EA5t h\xE1ch d\u1ECBch. Gh\xE9 ch\u01A1i nh\xE9!"), P("Water them a little every day and they will repay you with fruit.", "T\u01B0\u1EDBi m\u1ED9t ch\xFAt m\u1ED7i ng\xE0y, c\xE2y s\u1EBD \u0111\u1EC1n \u0111\xE1p b\u1EB1ng tr\xE1i ng\u1ECDt."), P("Your garden is growing so well. I can tell you care.", "V\u01B0\u1EDDn c\u1EE7a b\u1EA1n l\u1EDBn t\u1ED1t l\u1EAFm. M\xECnh bi\u1EBFt b\u1EA1n ch\u0103m l\u1EAFm.")],
  gift: [P("Friends do share nice things now and then. Keep meeting me!", "B\u1EA1n b\xE8 th\u1EC9nh tho\u1EA3ng s\u1EBD chia s\u1EBB \u0111\u1ED3 hay cho nhau. C\u1EE9 g\u1EB7p m\xECnh nh\xE9!"), P("Gifts are better as a surprise. I will think of something!", "Qu\xE0 t\u1EB7ng b\u1EA5t ng\u1EDD m\u1EDBi vui. M\xECnh s\u1EBD ngh\u0129 ra th\u1EE9 g\xEC \u0111\xF3!"), P("Patience, {name}. Good things come to friends who chat.", "Ki\xEAn nh\u1EABn nh\xE9 {name}. \u0110i\u1EC1u t\u1ED1t \u0111\u1EBFn v\u1EDBi nh\u1EEFng ng\u01B0\u1EDDi b\u1EA1n hay tr\xF2 chuy\u1EC7n.")],
  outfit: [P("I love dressing up. Fashion is just confidence you can wear.", "M\xECnh m\xEA di\u1EC7n \u0111\u1ED3. Th\u1EDDi trang l\xE0 s\u1EF1 t\u1EF1 tin m\u1EB7c \u0111\u01B0\u1EE3c l\xEAn ng\u01B0\u1EDDi."), P("Thanks! I picked this outfit after trying on everything.", "C\u1EA3m \u01A1n! M\xECnh ch\u1ECDn b\u1ED9 n\xE0y sau khi th\u1EED h\u1EBFt t\u1EE7 \u0111\u1ED3."), P("A good hat makes any day better. Trust me.", "M\u1ED9t c\xE1i m\u0169 \u0111\u1EB9p l\xE0m ng\xE0y n\xE0o c\u0169ng vui h\u01A1n. Tin m\xECnh \u0111i.")],
  fly: [P("Flying feels like a happy dream. The garden looks tiny from up there!", "Bay gi\u1ED1ng nh\u01B0 gi\u1EA5c m\u01A1 vui. Khu v\u01B0\u1EDDn nh\xECn t\u1EEB tr\xEAn cao b\xE9 x\xEDu!"), P("I cannot fly myself, but I love watching the ones who can.", "M\xECnh kh\xF4ng t\u1EF1 bay \u0111\u01B0\u1EE3c, nh\u01B0ng m\xECnh th\xEDch ng\u1EAFm ng\u01B0\u1EDDi bi\u1EBFt bay."), P("Wings or no wings, you can always reach for the sky.", "C\xF3 c\xE1nh hay kh\xF4ng, b\u1EA1n v\u1EABn lu\xF4n c\xF3 th\u1EC3 v\u01B0\u01A1n t\u1EDBi b\u1EA7u tr\u1EDDi.")],
  friend: [P("Friends are the best crop of all. They grow slowly and last forever.", "B\u1EA1n b\xE8 l\xE0 m\xF9a m\xE0ng t\u1ED1t nh\u1EA5t. L\u1EDBn ch\u1EADm m\xE0 b\u1EC1n m\xE3i."), P("I am glad we met, {name}. Truly.", "M\xECnh m\u1EEBng v\xEC \u0111\xE3 g\u1EB7p b\u1EA1n, {name}. Th\u1EADt \u0111\u1EA5y."), P("A friend is someone who listens, like you do.", "B\u1EA1n b\xE8 l\xE0 ng\u01B0\u1EDDi bi\u1EBFt l\u1EAFng nghe, nh\u01B0 b\u1EA1n v\u1EADy.")],
  joke: [P("Why did the carrot win? Because it was a root of all fun!", "T\u1EA1i sao c\xE0 r\u1ED1t th\u1EAFng cu\u1ED9c? V\xEC n\xF3 l\xE0 g\u1ED1c r\u1EC5 c\u1EE7a m\u1ECDi ni\u1EC1m vui!"), P("I tried to tell a farm joke, but it was too corny.", "M\xECnh k\u1EC3 chuy\u1EC7n c\u01B0\u1EDDi nh\xE0 n\xF4ng, nh\u01B0ng n\xF3 s\u1EBFn qu\xE1."), P("Haha! You made me snort like a little piglet.", "Haha! B\u1EA1n l\xE0m m\xECnh kh\u1ECBt m\u0169i nh\u01B0 ch\xFA heo con."), P("What do you call a sleeping goat? A nanny-nap! Okay, I will stop.", "Con d\xEA ng\u1EE7 g\u1ECDi l\xE0 g\xEC? D\xEA ng\u1EE7 g\u1EADt! Th\xF4i m\xECnh d\u1EEBng nh\xE9.")],
  praise: [P("Aw, thank you! You are the cool one around here.", "\xD4i c\u1EA3m \u01A1n b\u1EA1n! B\u1EA1n m\u1EDBi l\xE0 ng\u01B0\u1EDDi tuy\u1EC7t nh\u1EA5t \u1EDF \u0111\xE2y."), P("You are too kind, {name}. My cheeks are blushing.", "B\u1EA1n t\u1ED1t b\u1EE5ng qu\xE1 {name}. M\xECnh \u0111\u1ECF m\u1EB7t r\u1ED3i."), P("That is so sweet. Keep that kind spirit!", "Ng\u1ECDt ng\xE0o qu\xE1. C\u1EE9 gi\u1EEF tinh th\u1EA7n t\u1ED1t b\u1EE5ng \u1EA5y nh\xE9!")],
  name: [P("I am {me}! Nice to meet you properly, {name}.", "M\xECnh l\xE0 {me}! R\u1EA5t vui \u0111\u01B0\u1EE3c l\xE0m quen \u0111\xE0ng ho\xE0ng, {name}."), P("They call me {me}. Level {level}, and proud of it!", "M\u1ECDi ng\u01B0\u1EDDi g\u1ECDi m\xECnh l\xE0 {me}. C\u1EA5p {level}, v\xE0 m\xECnh t\u1EF1 h\xE0o l\u1EAFm!")],
  sad: [P("Oh no. Take a deep breath, {name}. Things get better, I promise.", "\xD4i kh\xF4ng. H\xEDt m\u1ED9t h\u01A1i th\u1EADt s\xE2u n\xE0o {name}. M\u1ECDi chuy\u1EC7n s\u1EBD \u1ED5n h\u01A1n, m\xECnh h\u1EE9a."), P("I am here for you. Maybe a walk in the garden will help?", "M\xECnh \u1EDF \u0111\xE2y v\u1EDBi b\u1EA1n. C\xF3 l\u1EBD \u0111i d\u1EA1o trong v\u01B0\u1EDDn s\u1EBD gi\xFAp \xEDch?"), P("Even the tallest tree started as a seed on a hard day. You will grow too.", "C\xE2y cao nh\u1EA5t c\u0169ng t\u1EEBng l\xE0 h\u1EA1t gi\u1ED1ng trong ng\xE0y kh\xF3 kh\u0103n. B\u1EA1n c\u0169ng s\u1EBD l\u1EDBn th\xF4i.")],
  question: [P("Hmm, good question. I will think about it while I walk.", "Hmm, c\xE2u h\u1ECFi hay \u0111\u1EA5y. M\xECnh s\u1EBD ngh\u0129 khi \u0111i d\u1EA1o."), P("I am not sure, {name}. What do you think?", "M\xECnh kh\xF4ng ch\u1EAFc, {name}. B\u1EA1n ngh\u0129 sao?"), P("Ooh, interesting! Ask me again later, I might have an answer.", "\u1ED2 th\xFA v\u1ECB! L\xE1t h\u1ECFi l\u1EA1i nh\xE9, bi\u1EBFt \u0111\xE2u m\xECnh c\xF3 c\xE2u tr\u1EA3 l\u1EDDi.")],
  other: [P("Tell me more, I like hearing from you.", "K\u1EC3 th\xEAm \u0111i, m\xECnh th\xEDch nghe b\u1EA1n n\xF3i."), P("That is nice, {name}. The valley is better with you in it.", "Hay \u0111\xF3 {name}. Thung l\u0169ng \u0111\u1EB9p h\u01A1n nh\u1EDD c\xF3 b\u1EA1n."), P("Hehe, I like the way you think.", "Hehe, m\xECnh th\xEDch c\xE1ch b\u1EA1n ngh\u0129."), P("Mm-hm! Go on, I am listening.", "\u1EEAm! N\xF3i ti\u1EBFp \u0111i, m\xECnh \u0111ang nghe \u0111\xE2y."), P("You always have something interesting to say.", "B\u1EA1n l\xFAc n\xE0o c\u0169ng c\xF3 \u0111i\u1EC1u th\xFA v\u1ECB \u0111\u1EC3 n\xF3i.")]
};
var FRIEND_EXTRA = [
  P("I am so happy we are friends, {name}.", "M\xECnh r\u1EA5t vui v\xEC ch\xFAng ta l\xE0 b\u1EA1n, {name}."),
  P("Come visit my garden any time. The door is always open.", "C\u1EE9 gh\xE9 v\u01B0\u1EDDn m\xECnh b\u1EA5t c\u1EE9 l\xFAc n\xE0o. C\u1EEDa lu\xF4n m\u1EDF."),
  P("Meeting you is one of the best parts of my day.", "G\u1EB7p b\u1EA1n l\xE0 m\u1ED9t trong nh\u1EEFng \u0111i\u1EC1u tuy\u1EC7t nh\u1EA5t c\u1EE7a ng\xE0y m\xECnh.")
];
var CHAT_VI = Object.fromEntries([...Object.values(CHAT_REPLIES).flat(), ...FRIEND_EXTRA].map(([en, vi]) => [en, vi]));

