var VI_UPGRADES = {
  "Upgrade bench": "B\xE0n n\xE2ng c\u1EA5p",
  "UPGRADE BENCH": "B\xC0N N\xC2NG C\u1EA4P",
  "Upgrade": "N\xE2ng c\u1EA5p",
  "Gear": "Trang b\u1ECB",
  "Skills": "K\u1EF9 n\u0103ng",
  "Level up the gear you own and your fighting skills. Weapons follow the same forge rules as the ember forge in the village.": "N\xE2ng c\u1EA5p trang b\u1ECB b\u1EA1n \u0111ang c\xF3 v\xE0 k\u1EF9 n\u0103ng chi\u1EBFn \u0111\u1EA5u. V\u0169 kh\xED theo \u0111\xFAng lu\u1EADt c\u01B0\u1EDDng h\xF3a c\u1EE7a l\xF2 r\xE8n than h\u1ED3ng trong l\xE0ng.",
  "Each skill levels up to 5. Levels work in every fight, online too.": "M\u1ED7i k\u1EF9 n\u0103ng n\xE2ng t\u1ED1i \u0111a c\u1EA5p 5. C\u1EA5p k\u1EF9 n\u0103ng c\xF3 hi\u1EC7u l\u1EF1c trong m\u1ECDi tr\u1EADn \u0111\u1EA5u, c\u1EA3 khi ch\u01A1i tr\u1EF1c tuy\u1EBFn.",
  "Upgrade for {energy} energy": "N\xE2ng c\u1EA5p v\u1EDBi {energy} n\u0103ng l\u01B0\u1EE3ng",
  "Buy hats, outfits, boots or companions first, then level them here.": "H\xE3y mua m\u0169, trang ph\u1EE5c, gi\xE0y ho\u1EB7c th\xFA \u0111\u1ED3ng h\xE0nh tr\u01B0\u1EDBc, r\u1ED3i n\xE2ng c\u1EA5p ch\xFAng \u1EDF \u0111\xE2y.",
  "Forge attempt: {chance}% chance of +1 \xB7 attack +{now}%": "C\u01B0\u1EDDng h\xF3a: {chance}% c\u01A1 h\u1ED9i +1 \xB7 t\u1EA5n c\xF4ng +{now}%",
  "Damage \xD7{damage} \xB7 radius +{radius} m": "S\xE1t th\u01B0\u01A1ng \xD7{damage} \xB7 b\xE1n k\xEDnh +{radius} m",
  "Damage \xD7{damage} \xB7 cooldown {cd} s": "S\xE1t th\u01B0\u01A1ng \xD7{damage} \xB7 h\u1ED3i chi\xEAu {cd} gi\xE2y",
  "Disguise skills keep their own power; these levels apply to your own four skills.": "K\u1EF9 n\u0103ng h\xF3a trang gi\u1EEF s\u1EE9c m\u1EA1nh ri\xEAng; c\xE1c c\u1EA5p n\xE0y \xE1p d\u1EE5ng cho b\u1ED1n k\u1EF9 n\u0103ng c\u1EE7a ch\xEDnh b\u1EA1n.",
  "Level {level} / {max}": "C\u1EA5p {level} / {max}",
  "Each level: +10% damage and +0.12 m spin radius.": "M\u1ED7i c\u1EA5p: +10% s\xE1t th\u01B0\u01A1ng v\xE0 +0,12 m b\xE1n k\xEDnh xo\xE1y.",
  "Each level: +10% damage and 0.2 s shorter cooldown.": "M\u1ED7i c\u1EA5p: +10% s\xE1t th\u01B0\u01A1ng v\xE0 h\u1ED3i chi\xEAu ng\u1EAFn h\u01A1n 0,2 gi\xE2y.",
  "Each level: +8% damage and +0.3 m shockwave radius.": "M\u1ED7i c\u1EA5p: +8% s\xE1t th\u01B0\u01A1ng v\xE0 +0,3 m b\xE1n k\xEDnh s\xF3ng ch\u1EA5n \u0111\u1ED9ng.",
  "Each level: +8% damage and 4% shorter cooldown for your weapon special.": "M\u1ED7i c\u1EA5p: +8% s\xE1t th\u01B0\u01A1ng v\xE0 h\u1ED3i chi\xEAu \u0111\u1EB7c bi\u1EC7t c\u1EE7a v\u0169 kh\xED ng\u1EAFn h\u01A1n 4%.",
  "{name} is now +{level}!": "{name} \u0111\xE3 l\xEAn +{level}!",
  "{skill} reached level {level}!": "{skill} \u0111\xE3 \u0111\u1EA1t c\u1EA5p {level}!",
  // Gear ceilings (gear-ceiling.ts): every item of a kind is equally strong at +10.
  "Level hats, outfits, boots and companions up to +10. At +10 every item of a kind is equally strong, so wear the look you like; items further behind cost more. Weapons use the forge: a 30% chance per attempt, +1% attack per level, up to +15.": "N\xE2ng m\u0169, trang ph\u1EE5c, gi\xE0y v\xE0 th\xFA \u0111\u1ED3ng h\xE0nh t\u1ED1i \u0111a +10. \u1EDE +10 m\u1ECDi m\xF3n c\xF9ng lo\u1EA1i \u0111\u1EC1u m\u1EA1nh nh\u01B0 nhau, n\xEAn h\xE3y m\u1EB7c ki\u1EC3u b\u1EA1n th\xEDch; m\xF3n c\xE0ng k\xE9m xa c\xE0ng t\u1ED1n nhi\u1EC1u. V\u0169 kh\xED d\xF9ng l\xF2 r\xE8n: m\u1ED7i l\u1EA7n th\u1EED c\xF3 30% c\u01A1 h\u1ED9i, +1% t\u1EA5n c\xF4ng m\u1ED7i c\u1EA5p, t\u1ED1i \u0111a +15.",
  "Lv {level}/{max} \xB7 at max: {stats}": "C\u1EA5p {level}/{max} \xB7 khi t\u1ED1i \u0111a: {stats}",
  "same for every hat": "m\u1ECDi m\u0169 \u0111\u1EC1u nh\u01B0 nhau",
  "same for every outfit": "m\u1ECDi trang ph\u1EE5c \u0111\u1EC1u nh\u01B0 nhau",
  "same for every pair of boots": "m\u1ECDi \u0111\xF4i gi\xE0y \u0111\u1EC1u nh\u01B0 nhau",
  "same for every companion": "m\u1ECDi th\xFA \u0111\u1ED3ng h\xE0nh \u0111\u1EC1u nh\u01B0 nhau",
  "Its shot stays its own: +{now}% damage": "Ph\xE1t b\u1EAFn v\u1EABn l\xE0 c\u1EE7a ri\xEAng n\xF3: +{now}% s\xE1t th\u01B0\u01A1ng",
  "\u03DF {energy} in all to reach +{max}": "\u03DF {energy} t\u1ED5ng c\u1ED9ng \u0111\u1EC3 \u0111\u1EA1t +{max}"
};

