var VI_HOUSE_TALK = {
  // Living room, kids
  "If I sit very still, the sofa thinks I am a cushion.": "T\u1EDB ng\u1ED3i im th\u1EADt im l\xE0 gh\u1EBF sofa t\u01B0\u1EDFng t\u1EDB l\xE0 c\xE1i g\u1ED1i \u0111\xF3.",
  "I built a pillow fort. Nobody may enter without a snack.": "T\u1EDB x\xE2y l\xE2u \u0111\xE0i g\u1ED1i r\u1ED3i. Mu\u1ED1n v\xE0o ph\u1EA3i n\u1ED9p b\xE1nh!",
  "Is the fire hungry? It keeps eating the logs.": "L\u1EEDa \u0111\xF3i h\u1EA3? N\xF3 c\u1EE9 \u0103n c\u1EE7i ho\xE0i.",
  "I counted the trophies. There are lots. Lots is a number.": 'T\u1EDB \u0111\u1EBFm c\xFAp r\u1ED3i. C\xF3 nhi\u1EC1u l\u1EAFm. "Nhi\u1EC1u l\u1EAFm" l\xE0 m\u1ED9t con s\u1ED1 nha.',
  "When I grow up I want to be taller. That is my whole plan.": "L\u1EDBn l\xEAn t\u1EDB mu\u1ED1n cao h\u01A1n. K\u1EBF ho\u1EA1ch c\u1EE7a t\u1EDB ch\u1EC9 c\xF3 v\u1EADy th\xF4i.",
  "The radio is singing again. Can it hear us back?": "C\xE1i \u0111\xE0i l\u1EA1i h\xE1t n\u1EEFa k\xECa. N\xF3 c\xF3 nghe t\u1EE5i m\xECnh n\xF3i kh\xF4ng?",
  "I am not tired. My eyes are just resting with the lights off.": "T\u1EDB kh\xF4ng bu\u1ED3n ng\u1EE7. M\u1EAFt t\u1EDB ch\u1EC9 t\u1EAFt \u0111\xE8n ngh\u1EC9 ch\xFAt th\xF4i.",
  "Can we have a party? A small one? With cake?": "M\xECnh l\xE0m ti\u1EC7c \u0111\u01B0\u1EE3c kh\xF4ng? Nh\u1ECF th\xF4i? C\xF3 b\xE1nh kem nha?",
  "I found a crumb in the sofa. Finders keepers!": "T\u1EDB t\xECm th\u1EA5y v\u1EE5n b\xE1nh trong gh\u1EBF. Ai th\u1EA5y tr\u01B0\u1EDBc l\xE0 c\u1EE7a ng\u01B0\u1EDDi \u0111\xF3!",
  // Living room, grown-ups
  "Ah, the sofa. My favourite place in all nine worlds.": "A, c\xE1i sofa. Ch\u1ED7 m\xECnh th\xEDch nh\u1EA5t trong c\u1EA3 ch\xEDn th\u1EBF gi\u1EDBi.",
  "Someone keeps moving the cushions. I know it is you.": "C\xF3 ai c\u1EE9 d\u1EDDi g\u1ED1i ho\xE0i. M\xECnh bi\u1EBFt l\xE0 b\u1EA1n \u0111\xF3 nha.",
  "Nothing beats a warm fire after a long day out.": "\u0110i c\u1EA3 ng\xE0y v\u1EC1, ng\u1ED3i b\xEAn l\u1EEDa \u1EA5m l\xE0 nh\u1EA5t.",
  "Look at that trophy shelf. We will need a bigger shelf.": "Nh\xECn k\u1EC7 c\xFAp k\xECa. Ch\u1EAFc ph\u1EA3i \u0111\xF3ng k\u1EC7 to h\u01A1n r\u1ED3i.",
  "Put the kettle on, would you? Just one cup. Maybe two.": "\u0110un n\u01B0\u1EDBc gi\xF9m m\xECnh nh\xE9? M\u1ED9t t\xE1ch th\xF4i. Ch\u1EAFc hai.",
  "I sat down for one minute and an hour went by.": "M\u1EDBi ng\u1ED3i xu\u1ED1ng m\u1ED9t ph\xFAt m\xE0 \u0111\xE3 tr\xF4i qua m\u1ED9t ti\u1EBFng.",
  "This tune again? Fine. It is a good tune.": "L\u1EA1i b\xE0i n\xE0y \xE0? Th\xF4i \u0111\u01B0\u1EE3c. B\xE0i n\xE0y hay m\xE0.",
  "You could at least wipe your boots before the rug.": "\xCDt ra c\u0169ng ch\xF9i gi\xE0y tr\u01B0\u1EDBc khi gi\u1EABm l\xEAn th\u1EA3m ch\u1EE9.",
  "A quiet evening at home. Exactly what I ordered.": "M\u1ED9t bu\u1ED5i t\u1ED1i y\xEAn \u1EA3 \u1EDF nh\xE0. \u0110\xFAng nh\u01B0 m\xECnh mong.",
  // Kitchen, kids
  "Can I lick the spoon? Just the spoon. Not the pot.": "Cho t\u1EDB li\u1EBFm c\xE1i mu\u1ED7ng nha? Mu\u1ED7ng th\xF4i. Kh\xF4ng li\u1EBFm n\u1ED3i \u0111\xE2u.",
  "Carrots help you see in the dark. I am trying it now.": "\u0102n c\xE0 r\u1ED1t th\xEC nh\xECn \u0111\u01B0\u1EE3c trong t\u1ED1i. T\u1EDB \u0111ang th\u1EED n\xE8.",
  "I am not hungry. My tummy is just very loud.": "T\u1EDB kh\xF4ng \u0111\xF3i. B\u1EE5ng t\u1EDB ch\u1EC9 k\xEAu to th\xF4i.",
  "Why is it called a cupcake if you cannot drink it?": 'Sao g\u1ECDi l\xE0 b\xE1nh "c\u1ED1c" m\xE0 kh\xF4ng u\u1ED1ng \u0111\u01B0\u1EE3c?',
  "I helped! I stirred it twice and only spilled once.": "T\u1EDB ph\u1EE5 r\u1ED3i n\xE8! Khu\u1EA5y hai l\u1EA7n m\xE0 ch\u1EC9 l\xE0m \u0111\u1ED5 c\xF3 m\u1ED9t l\u1EA7n.",
  "The kettle is whistling. Who taught it that song?": "\u1EA4m n\u01B0\u1EDBc \u0111ang hu\xFDt s\xE1o. Ai d\u1EA1y n\xF3 b\xE0i \u0111\xF3 v\u1EADy?",
  "I want soup with no green bits. Only happy bits.": "T\u1EDB mu\u1ED1n s\xFAp kh\xF4ng c\xF3 mi\u1EBFng xanh. Ch\u1EC9 c\xF3 mi\u1EBFng vui th\xF4i.",
  "Is it dinner yet? How about now? How about now?": "T\u1EDBi gi\u1EDD \u0103n ch\u01B0a? Gi\u1EDD th\xEC sao? C\xF2n gi\u1EDD?",
  "If I eat my peas fast, do they count as dessert?": "T\u1EDB \u0103n \u0111\u1EADu th\u1EADt nhanh th\xEC c\xF3 t\xEDnh l\xE0 m\xF3n tr\xE1ng mi\u1EC7ng kh\xF4ng?",
  // Kitchen, grown-ups
  "Who left the lid off the honey jar? Again?": "Ai l\u1EA1i qu\xEAn \u0111\u1EADy n\u1EAFp h\u0169 m\u1EADt ong n\u1EEFa v\u1EADy?",
  "A pinch of salt, a pinch more, and\u2026 perfect.": "M\u1ED9t nh\xFAm mu\u1ED1i, th\xEAm nh\xFAm n\u1EEFa, v\xE0\u2026 ho\xE0n h\u1EA3o.",
  "Soup is nearly ready. Do not touch the pot.": "S\xFAp s\u1EAFp xong r\u1ED3i. \u0110\u1EEBng \u0111\u1EE5ng v\xE0o n\u1ED3i nha.",
  "Fresh veggies from our own garden taste twice as nice.": "Rau nh\xE0 tr\u1ED3ng \u0103n ngon g\u1EA5p \u0111\xF4i.",
  "I will do the dishes. Tomorrow. First thing.": "M\xECnh s\u1EBD r\u1EEDa ch\xE9n. Ng\xE0y mai. Vi\u1EC7c \u0111\u1EA7u ti\xEAn lu\xF4n.",
  "Tea is the answer. I forget the question.": "Tr\xE0 l\xE0 c\xE2u tr\u1EA3 l\u1EDDi. C\xE2u h\u1ECFi th\xEC m\xECnh qu\xEAn r\u1ED3i.",
  "We are out of sugar. And someone ate the last biscuit.": "H\u1EBFt \u0111\u01B0\u1EDDng r\u1ED3i. M\xE0 ai \u0103n m\u1EA5t c\xE1i b\xE1nh quy cu\u1ED1i c\xF9ng n\u1EEFa.",
  "Smell that? That is the smell of a well-earned lunch.": "Ng\u1EEDi th\u1EA5y kh\xF4ng? M\xF9i b\u1EEFa tr\u01B0a x\u1EE9ng \u0111\xE1ng \u0111\xF3.",
  "Cooking for friends is my favourite kind of busy.": "N\u1EA5u cho b\u1EA1n b\xE8 \u0103n l\xE0 ki\u1EC3u b\u1EADn r\u1ED9n m\xECnh th\xEDch nh\u1EA5t.",
  // Craft room, kids
  "I painted a cat. It looks like a potato. A cat potato.": "T\u1EDB v\u1EBD con m\xE8o. Nh\xECn gi\u1ED1ng c\u1EE7 khoai. M\xE8o khoai t\xE2y.",
  "Glitter goes everywhere. Even in my ears.": "Kim tuy\u1EBFn bay kh\u1EAFp n\u01A1i. V\xF4 c\u1EA3 l\u1ED7 tai t\u1EDB lu\xF4n.",
  "This is a dragon. Or a cloud. It is still deciding.": "\u0110\xE2y l\xE0 con r\u1ED3ng. Ho\u1EB7c \u0111\xE1m m\xE2y. N\xF3 v\u1EABn \u0111ang suy ngh\u0129.",
  "I made you a present. Please do not look until I say.": "T\u1EDB l\xE0m qu\xE0 cho c\u1EADu n\xE8. Ch\u01B0a \u0111\u01B0\u1EE3c nh\xECn \u0111\xE2u nha.",
  "Blue and yellow made green! I am a wizard!": "Xanh d\u01B0\u01A1ng v\u1EDBi v\xE0ng th\xE0nh xanh l\xE1! T\u1EDB l\xE0 ph\xF9 th\u1EE7y!",
  "Can I hammer something? Anything? Please?": "Cho t\u1EDB \u0111\xF3ng b\xFAa c\xE1i g\xEC \u0111i? C\xE1i g\xEC c\u0169ng \u0111\u01B0\u1EE3c? N\u0103n n\u1EC9 m\xE0?",
  "My picture needs more purple. Everything needs more purple.": "Tranh t\u1EDB c\u1EA7n th\xEAm m\xE0u t\xEDm. C\xE1i g\xEC c\u0169ng c\u1EA7n th\xEAm m\xE0u t\xEDm.",
  "I drew our house, but bigger, with a slide on the roof.": "T\u1EDB v\u1EBD nh\xE0 m\xECnh, m\xE0 to h\u01A1n, c\xF3 c\u1EA7u tu\u1ED9t tr\xEAn m\xE1i n\u1EEFa.",
  "Oops. That was not supposed to be glued to my hand.": "\u1ED0i. C\xE1i \u0111\xF3 \u0111\xE2u ph\u1EA3i \u0111\u1EC3 d\xE1n v\xF4 tay t\u1EDB.",
  // Craft room, grown-ups
  "Measure twice, cut once. I measured three times, to be safe.": "\u0110o hai l\u1EA7n, c\u1EAFt m\u1ED9t l\u1EA7n. M\xECnh \u0111o ba l\u1EA7n cho ch\u1EAFc.",
  "That painting is coming along nicely. Bold use of orange.": "B\u1EE9c tranh ti\u1EBFn tri\u1EC3n t\u1ED1t \u0111\xF3. D\xF9ng m\xE0u cam t\xE1o b\u1EA1o gh\xEA.",
  "Has anyone seen the good scissors? They walk off by themselves.": "C\xF3 ai th\u1EA5y c\xE2y k\xE9o x\u1ECBn kh\xF4ng? N\xF3 c\u1EE9 t\u1EF1 \u0111i \u0111\xE2u m\u1EA5t.",
  "One more coat of paint and it is done. Probably.": "Th\xEAm m\u1ED9t l\u1EDBp s\u01A1n n\u1EEFa l\xE0 xong. Ch\u1EAFc v\u1EADy.",
  "A tidy workbench is a happy workbench. In theory.": "B\xE0n l\xE0m vi\u1EC7c g\u1ECDn l\xE0 b\xE0n l\xE0m vi\u1EC7c vui. Tr\xEAn l\xFD thuy\u1EBFt.",
  "I keep every string and button. You never know.": "S\u1EE3i ch\u1EC9, c\xE1i n\xFAt n\xE0o m\xECnh c\u0169ng gi\u1EEF. Bi\u1EBFt \u0111\xE2u c\u1EA7n.",
  "The light in here is perfect for painting this time of day.": "Gi\u1EDD n\xE0y \xE1nh s\xE1ng trong ph\xF2ng v\u1EBD tranh \u0111\u1EB9p nh\u1EA5t.",
  "Making something by hand is the best kind of slow.": "T\u1EF1 tay l\xE0m \u0111\u1ED3 l\xE0 ki\u1EC3u ch\u1EADm r\xE3i d\u1EC5 ch\u1ECBu nh\u1EA5t.",
  "Careful, that paint is still wet. Ask me how I know.": "C\u1EA9n th\u1EADn, s\u01A1n c\xF2n \u01B0\u1EDBt \u0111\xF3. \u0110\u1EEBng h\u1ECFi sao m\xECnh bi\u1EBFt.",
  // Bedroom, kids
  "I am not sleepy. I am just practising yawning.": "T\u1EDB kh\xF4ng bu\u1ED3n ng\u1EE7. T\u1EDB \u0111ang t\u1EADp ng\xE1p th\xF4i.",
  "Can you check under the bed? Just in case it is a monster. A nice one.": "C\u1EADu xem d\u01B0\u1EDBi g\u1EA7m gi\u01B0\u1EDDng gi\xF9m t\u1EDB? L\u1EE1 c\xF3 qu\xE1i v\u1EADt. Qu\xE1i v\u1EADt hi\u1EC1n th\xF4i.",
  "One more story. A short one. A medium one.": "K\u1EC3 th\xEAm m\u1ED9t chuy\u1EC7n n\u1EEFa. Ng\u1EAFn th\xF4i. V\u1EEBa v\u1EEBa th\xF4i.",
  "My teddy is scared of the dark, so the light stays on.": "G\u1EA5u b\xF4ng c\u1EE7a t\u1EDB s\u1EE3 t\u1ED1i, n\xEAn ph\u1EA3i \u0111\u1EC3 \u0111\xE8n nha.",
  "I can jump on the bed? No? What about bounce a little?": "T\u1EDB nh\u1EA3y tr\xEAn gi\u01B0\u1EDDng \u0111\u01B0\u1EE3c kh\xF4ng? Kh\xF4ng h\u1EA3? Nh\xFAn nh\xFAn ch\xFAt th\xF4i?",
  "When I dream, I can fly. And eat ice cream for lunch.": "Trong m\u01A1 t\u1EDB bay \u0111\u01B0\u1EE3c. C\xF2n \u0103n kem thay c\u01A1m tr\u01B0a n\u1EEFa.",
  "My socks are lost. They went on holiday without me.": "V\u1EDB c\u1EE7a t\u1EDB m\u1EA5t r\u1ED3i. Ch\u1EAFc t\u1EE5i n\xF3 \u0111i du l\u1ECBch b\u1ECF t\u1EDB \u1EDF nh\xE0.",
  "Is it morning yet? It feels like it should be morning.": "S\xE1ng ch\u01B0a v\u1EADy? T\u1EDB th\u1EA5y gi\u1ED1ng s\xE1ng r\u1ED3i \u0111\xF3.",
  "I tucked myself in all by myself. Look, a burrito!": "T\u1EDB t\u1EF1 \u0111\u1EAFp ch\u0103n m\u1ED9t m\xECnh \u0111\xF3. Nh\xECn n\xE8, t\u1EDB l\xE0 c\xE1i b\xE1nh cu\u1ED1n!",
  // Bedroom, grown-ups
  "A proper bed and a proper sleep. That is luxury.": "M\u1ED9t c\xE1i gi\u01B0\u1EDDng t\u1EED t\u1EBF v\xE0 m\u1ED9t gi\u1EA5c ng\u1EE7 ngon. Xa x\u1EC9 th\u1EADt.",
  "I will fold the laundry. Right after this little lie-down.": "M\xECnh s\u1EBD g\u1EA5p \u0111\u1ED3. Ngay sau khi n\u1EB1m ngh\u1EC9 m\u1ED9t x\xEDu.",
  "Who knew pillows could be this fluffy?": "Ai ng\u1EDD g\u1ED1i l\u1EA1i \xEAm \u0111\u1EBFn v\u1EADy ch\u1EE9?",
  "Early night tonight. I mean it this time.": "T\u1ED1i nay ng\u1EE7 s\u1EDBm. L\u1EA7n n\xE0y n\xF3i th\u1EADt \u0111\xF3.",
  "This wardrobe is full and I still have nothing to wear.": "T\u1EE7 \u0111\u1ED3 ch\u1EADt c\u1EE9ng m\xE0 v\u1EABn kh\xF4ng c\xF3 g\xEC \u0111\u1EC3 m\u1EB7c.",
  "Ah, morning stretches. Everything goes pop.": "A, v\u01B0\u01A1n vai bu\u1ED5i s\xE1ng. Kh\u1EDBp n\xE0o c\u0169ng k\xEAu r\u0103ng r\u1EAFc.",
  "Open the curtains, the garden looks lovely today.": "K\xE9o r\xE8m ra \u0111i, h\xF4m nay v\u01B0\u1EDDn \u0111\u1EB9p l\u1EAFm.",
  "Five more minutes. Then I am up. Ten at most.": "N\u0103m ph\xFAt n\u1EEFa th\xF4i. R\u1ED3i d\u1EADy. C\xF9ng l\u1EAFm m\u01B0\u1EDDi ph\xFAt.",
  "Sweet dreams, everyone. No snoring this time, please.": "Ng\u1EE7 ngon c\u1EA3 nh\xE0. L\u1EA7n n\xE0y \u0111\u1EEBng ng\xE1y nha.",
  // Bathroom, kids
  "The duck says the water is too warm. I asked him.": "V\u1ECBt n\xF3i n\u01B0\u1EDBc \u1EA5m qu\xE1. T\u1EDB h\u1ECFi n\xF3 r\u1ED3i.",
  "Bubbles! I have a bubble beard! Call me Grandpa!": "Bong b\xF3ng! T\u1EDB c\xF3 r\xE2u bong b\xF3ng! G\u1ECDi t\u1EDB l\xE0 \xF4ng n\u1ED9i \u0111i!",
  "My fingers went all wrinkly. Am I turning into a raisin?": "Ng\xF3n tay t\u1EDB nh\u0103n nheo h\u1EBFt r\u1ED3i. T\u1EDB s\u1EAFp th\xE0nh nho kh\xF4 h\u1EA3?",
  "I brushed my teeth. Well, I brushed one tooth really well.": "T\u1EDB \u0111\xE1nh r\u0103ng r\u1ED3i. Th\xEC\u2026 \u0111\xE1nh th\u1EADt k\u1EF9 m\u1ED9t c\xE1i r\u0103ng.",
  "Can I stay in the bath until I am a fish?": "T\u1EDB \u1EDF trong b\u1ED3n t\u1EAFm t\u1EDBi khi th\xE0nh con c\xE1 \u0111\u01B0\u1EE3c kh\xF4ng?",
  "Where does the water go when it goes down the hole?": "N\u01B0\u1EDBc chui xu\u1ED1ng l\u1ED7 r\u1ED3i \u0111i \u0111\xE2u v\u1EADy?",
  "The mirror is foggy. I drew a smiley face.": "G\u01B0\u01A1ng m\u1EDD h\u01A1i n\u01B0\u1EDBc. T\u1EDB v\u1EBD m\u1EB7t c\u01B0\u1EDDi l\xEAn \u0111\xF3.",
  "Soap is slippery on purpose. It does not want to be used.": "X\xE0 ph\xF2ng c\u1ED1 t\xECnh tr\u01A1n \u0111\xF3. N\xF3 kh\xF4ng mu\u1ED1n b\u1ECB x\xE0i.",
  "Splash! Oops. The floor wanted a bath too.": "\xD9m! \u1ED0i. S\xE0n nh\xE0 c\u0169ng mu\u1ED1n \u0111\u01B0\u1EE3c t\u1EAFm.",
  // Bathroom, grown-ups
  "A hot bath fixes almost everything.": "T\u1EAFm n\u01B0\u1EDBc n\xF3ng l\xE0 ch\u1EEFa \u0111\u01B0\u1EE3c g\u1EA7n h\u1EBFt m\u1ECDi chuy\u1EC7n.",
  "Who used all the hot water? I have my suspicions.": "Ai x\xE0i h\u1EBFt n\u01B0\u1EDBc n\xF3ng v\u1EADy? M\xECnh nghi r\u1ED3i \u0111\xF3.",
  "Hang your towel up, it will dry much faster.": "Treo kh\u0103n l\xEAn \u0111i, kh\xF4 nhanh h\u01A1n nhi\u1EC1u.",
  "Look at that sparkle. I scrubbed this sink myself.": "Nh\xECn b\u1ED3n r\u1EEDa s\xE1ng b\xF3ng ch\u01B0a. T\u1EF1 tay m\xECnh c\u1ECD \u0111\xF3.",
  "The duck stays. The duck always stays.": "Con v\u1ECBt \u1EDF l\u1EA1i. Con v\u1ECBt l\xFAc n\xE0o c\u0169ng \u1EDF l\u1EA1i.",
  "Two minutes for teeth. The whole two minutes.": "\u0110\xE1nh r\u0103ng hai ph\xFAt. \u0110\u1EE7 hai ph\xFAt nha.",
  "Ah, fresh as a daisy. A slightly damp daisy.": "A, t\u01B0\u01A1i nh\u01B0 hoa c\xFAc. Hoa c\xFAc h\u01A1i \u01B0\u1EDBt m\u1ED9t ch\xFAt.",
  "Mind the floor, it is slippery after the bath.": "Coi ch\u1EEBng s\xE0n, t\u1EAFm xong tr\u01A1n l\u1EAFm.",
  "Bubble baths after a long day are a must.": "M\u1EC7t c\u1EA3 ng\xE0y th\xEC ph\u1EA3i ng\xE2m b\u1ED3n b\u1ECDt th\xF4i.",
  // Study, kids
  "This book has no pictures. How do they know what happens?": "S\xE1ch n\xE0y kh\xF4ng c\xF3 h\xECnh. Sao ng\u01B0\u1EDDi ta bi\u1EBFt chuy\u1EC7n g\xEC x\u1EA3y ra?",
  "I read a whole page! Well, I looked at it very hard.": "T\u1EDB \u0111\u1ECDc h\u1EBFt m\u1ED9t trang r\u1ED3i! Th\xEC\u2026 t\u1EDB nh\xECn n\xF3 r\u1EA5t ch\u0103m ch\xFA.",
  "If I spin the globe and stop it, can we go there?": "T\u1EDB quay qu\u1EA3 \u0111\u1ECBa c\u1EA7u r\u1ED3i ch\u1EC9 tr\xFAng ch\u1ED7 n\xE0o, m\xECnh \u0111i ch\u1ED7 \u0111\xF3 nha?",
  "Did you know some fish can glow? I want to glow.": "C\u1EADu bi\u1EBFt c\xF3 lo\xE0i c\xE1 ph\xE1t s\xE1ng kh\xF4ng? T\u1EDB c\u0169ng mu\u1ED1n ph\xE1t s\xE1ng.",
  "Shh! The books are sleeping. Read quietly.": "Su\u1EF5t! S\xE1ch \u0111ang ng\u1EE7. \u0110\u1ECDc nh\u1ECF nh\u1ECF th\xF4i.",
  "I am writing a diary. Today I was brave. Twice.": "T\u1EDB \u0111ang vi\u1EBFt nh\u1EADt k\xFD. H\xF4m nay t\u1EDB d\u0169ng c\u1EA3m. Hai l\u1EA7n lu\xF4n.",
  "How many worlds are there? More than ten? More than eleven?": "C\xF3 bao nhi\xEAu th\u1EBF gi\u1EDBi v\u1EADy? H\u01A1n m\u01B0\u1EDDi kh\xF4ng? H\u01A1n m\u01B0\u1EDDi m\u1ED9t kh\xF4ng?",
  "Is that star a planet? Can we visit it after lunch?": "Ng\xF4i sao kia l\xE0 h\xE0nh tinh h\u1EA3? \u0102n tr\u01B0a xong m\xECnh gh\xE9 \u0111\u01B0\u1EE3c kh\xF4ng?",
  "I know all my letters except the wiggly ones.": "T\u1EDB thu\u1ED9c h\u1EBFt ch\u1EEF c\xE1i, tr\u1EEB m\u1EA5y ch\u1EEF ngo\u1EB1n ngo\xE8o.",
  // Study, grown-ups
  "Just one more chapter. Then bed. Honestly.": "Th\xEAm m\u1ED9t ch\u01B0\u01A1ng n\u1EEFa th\xF4i. R\u1ED3i \u0111i ng\u1EE7. Th\u1EADt m\xE0.",
  "This map shows a world we have not been to yet.": "B\u1EA3n \u0111\u1ED3 n\xE0y c\xF3 m\u1ED9t th\u1EBF gi\u1EDBi t\u1EE5i m\xECnh ch\u01B0a t\u1EDBi.",
  "The bookshelf is full. Time to build another bookshelf.": "K\u1EC7 s\xE1ch \u0111\u1EA7y r\u1ED3i. T\u1EDBi l\xFAc \u0111\xF3ng th\xEAm k\u1EC7 n\u1EEFa.",
  "Note to self: write down where you put your notes.": "T\u1EF1 nh\u1EAFc: ghi l\u1EA1i ch\u1ED7 \u0111\u1EC3 m\u1EA5y t\u1EDD ghi ch\xFA.",
  "Quiet in here. Perfect for thinking big thoughts.": "Trong n\xE0y y\xEAn t\u0129nh. H\u1EE3p \u0111\u1EC3 ngh\u0129 chuy\u1EC7n l\u1EDBn.",
  "I read that some fish only bite at sunrise. Interesting.": "M\xECnh \u0111\u1ECDc th\u1EA5y c\xF3 lo\xE0i c\xE1 ch\u1EC9 c\u1EAFn c\xE2u l\xFAc b\xECnh minh. Hay gh\xEA.",
  "Our collection is really growing. Look at these pages.": "B\u1ED9 s\u01B0u t\u1EADp l\u1EDBn d\u1EA7n r\u1ED3i. Nh\xECn m\u1EA5y trang n\xE0y xem.",
  "Planning tomorrow already. Big day, lots of watering.": "\u0110ang t\xEDnh chuy\u1EC7n ng\xE0y mai r\u1ED3i. Ng\xE0y b\u1EADn, t\u01B0\u1EDBi c\xE2y nhi\u1EC1u.",
  "A good book and a cup of tea. That is my evening.": "M\u1ED9t cu\u1ED1n s\xE1ch hay v\u1EDBi m\u1ED9t t\xE1ch tr\xE0. Bu\u1ED5i t\u1ED1i c\u1EE7a m\xECnh \u0111\xF3.",
  // Personas
  "I planted a jelly bean. Tomorrow we get a jelly bean tree!": "T\u1EDB tr\u1ED3ng m\u1ED9t vi\xEAn k\u1EB9o d\u1EBBo. Mai m\xECnh c\xF3 c\xE2y k\u1EB9o d\u1EBBo!",
  "Worms are my friends. They are very wiggly friends.": "Giun l\xE0 b\u1EA1n t\u1EDB. M\u1EA5y ng\u01B0\u1EDDi b\u1EA1n ng\u1ECD ngu\u1EADy l\u1EAFm.",
  "I whispered to the carrots so they grow faster.": "T\u1EDB th\xEC th\u1EA7m v\u1EDBi c\xE0 r\u1ED1t \u0111\u1EC3 t\u1EE5i n\xF3 mau l\u1EDBn.",
  "The beds need water at sunrise, before the heat.": "Lu\u1ED1ng c\xE2y ph\u1EA3i t\u01B0\u1EDBi l\xFAc b\xECnh minh, tr\u01B0\u1EDBc khi n\u1EAFng g\u1EAFt.",
  "I swear the pumpkins grow while you watch them.": "Th\u1EC1 lu\xF4n, b\xED ng\xF4 l\u1EDBn ngay tr\u01B0\u1EDBc m\u1EAFt m\xECnh.",
  "Upgraded beds are wonderful. Everything grows so quickly now.": "Lu\u1ED1ng n\xE2ng c\u1EA5p tuy\u1EC7t th\u1EADt. Gi\u1EDD c\xE1i g\xEC c\u0169ng l\u1EDBn nhanh.",
  "The chickens said hello. Well, they said bok. Same thing.": 'M\u1EA5y con g\xE0 ch\xE0o t\u1EDB \u0111\xF3. T\u1EE5i n\xF3 n\xF3i "c\u1EE5c t\xE1c". C\u0169ng v\u1EADy th\xF4i.',
  "I want to ride a cow. A slow one.": "T\u1EDB mu\u1ED1n c\u01B0\u1EE1i b\xF2. Con n\xE0o \u0111i ch\u1EADm ch\u1EADm.",
  "The pig rolled in mud and looked so happy!": "Heo l\u0103n trong b\xF9n m\xE0 vui gh\xEA lu\xF4n!",
  "The hens laid six eggs this morning. Good girls.": "S\xE1ng nay g\xE0 m\xE1i \u0111\u1EBB s\xE1u tr\u1EE9ng. Gi\u1ECFi l\u1EAFm m\u1EA5y c\u01B0ng.",
  "Feeding time is the best time. Everyone is so pleased to see me.": "Gi\u1EDD cho \u0103n l\xE0 vui nh\u1EA5t. \u0110\u1EE9a n\xE0o th\u1EA5y m\xECnh c\u0169ng m\u1EEBng.",
  "A farm never sleeps. But I do. Goodnight.": "N\xF4ng tr\u1EA1i kh\xF4ng bao gi\u1EDD ng\u1EE7. Nh\u01B0ng m\xECnh th\xEC c\xF3. Ch\xFAc ng\u1EE7 ngon.",
  "I made a soup! It is mostly water and one carrot.": "T\u1EDB n\u1EA5u s\xFAp n\xE8! Ch\u1EE7 y\u1EBFu l\xE0 n\u01B0\u1EDBc v\u1EDBi m\u1ED9t c\u1EE7 c\xE0 r\u1ED1t.",
  "Pancakes are just flat cakes. Flat cakes are the best cakes.": "B\xE1nh k\u1EBFp l\xE0 b\xE1nh d\u1EB9p. B\xE1nh d\u1EB9p l\xE0 b\xE1nh ngon nh\u1EA5t.",
  "Can I crack the egg? I will be gentle. Mostly.": "Cho t\u1EDB \u0111\u1EADp tr\u1EE9ng nha? T\u1EDB nh\u1EB9 tay m\xE0. H\u1EA7u h\u1EBFt l\xE0 v\u1EADy.",
  "A pinch of chili wakes up any stew.": "M\u1ED9t nh\xFAm \u1EDBt l\xE0 m\xF3n h\u1EA7m n\xE0o c\u0169ng t\u1EC9nh c\u1EA3 ng\u01B0\u1EDDi.",
  "Good food, good friends, good evening.": "\u0110\u1ED3 \u0103n ngon, b\u1EA1n b\xE8 t\u1ED1t, bu\u1ED5i t\u1ED1i \u0111\u1EB9p.",
  "Never trust a cook who does not taste as they go.": "\u0110\u1EEBng tin \u0111\u1EA7u b\u1EBFp n\xE0o n\u1EA5u m\xE0 kh\xF4ng n\u1EBFm.",
  // Exchanges
  "Is it my turn on the comfy cushion?": "T\u1EDBi l\u01B0\u1EE3t t\u1EDB ng\u1ED3i g\u1ED1i \xEAm ch\u01B0a?",
  "It is always your turn, apparently.": "H\xECnh nh\u01B0 l\xFAc n\xE0o c\u0169ng t\u1EDBi l\u01B0\u1EE3t c\u1EADu.",
  "Who wants to hear about my day?": "Ai mu\u1ED1n nghe chuy\u1EC7n h\xF4m nay c\u1EE7a m\xECnh kh\xF4ng?",
  "Only if it ends with a snack.": "N\u1EBFu k\u1EBFt th\xFAc b\u1EB1ng \u0111\u1ED3 \u0103n v\u1EB7t th\xEC nghe.",
  "What is for dinner?": "T\u1ED1i nay \u0103n g\xEC v\u1EADy?",
  "Food. Now set the table, please.": "\u0102n c\u01A1m. Gi\u1EDD d\u1ECDn b\xE0n gi\xF9m nha.",
  "Can I help cook?": "T\u1EDB ph\u1EE5 n\u1EA5u \u0111\u01B0\u1EE3c kh\xF4ng?",
  "Yes! Start by washing those hands.": "\u0110\u01B0\u1EE3c! \u0110i r\u1EEDa tay tr\u01B0\u1EDBc \u0111\xE3.",
  "Do you like my painting?": "C\u1EADu th\xEDch tranh t\u1EDB kh\xF4ng?",
  "I love it. Which way up does it go?": "Th\xEDch l\u1EAFm. M\xE0 treo \u0111\u1EA7u n\xE0o l\xEAn tr\xEAn v\u1EADy?",
  "I need the glue.": "T\u1EDB c\u1EA7n h\u1ED3 d\xE1n.",
  "It is stuck to your elbow.": "N\xF3 \u0111ang d\xEDnh tr\xEAn khu\u1EF7u tay c\u1EADu k\xECa.",
  "Are you awake?": "C\u1EADu c\xF2n th\u1EE9c kh\xF4ng?",
  "I am now.": "Gi\u1EDD th\xEC th\u1EE9c r\u1ED3i.",
  "Goodnight!": "Ng\u1EE7 ngon!",
  "Goodnight! Do not let the bed bugs bite. We do not have any.": "Ng\u1EE7 ngon! Coi ch\u1EEBng r\u1EC7p c\u1EAFn. \xC0 m\xE0 nh\xE0 m\xECnh kh\xF4ng c\xF3 r\u1EC7p.",
  "Bath time!": "T\u1EDBi gi\u1EDD t\u1EAFm r\u1ED3i!",
  "Do I have to? I was clean last week.": "Ph\u1EA3i t\u1EAFm h\u1EA3? Tu\u1EA7n tr\u01B0\u1EDBc t\u1EDB s\u1EA1ch r\u1ED3i m\xE0.",
  "Have you seen the duck?": "C\xF3 ai th\u1EA5y con v\u1ECBt kh\xF4ng?",
  "He is in the bath. Where else would he be?": "N\xF3 \u1EDF trong b\u1ED3n t\u1EAFm. Ch\u1EE9 c\xF2n \u1EDF \u0111\xE2u n\u1EEFa?",
  "What does this word mean?": "Ch\u1EEF n\xE0y ngh\u0129a l\xE0 g\xEC v\u1EADy?",
  "Look it up. That is what the big book is for.": "Tra \u0111i. Cu\u1ED1n s\xE1ch to \u0111\xF3 \u0111\u1EC3 l\xE0m v\u1EADy m\xE0.",
  "Shh, I am reading.": "Su\u1EF5t, m\xECnh \u0111ang \u0111\u1ECDc.",
  "You are holding it upside down.": "C\u1EADu \u0111ang c\u1EA7m ng\u01B0\u1EE3c k\xECa.",
  // Garden, farm and cook extras, the boss, exchanges
  "The tomatoes are blushing. I think they like me.": "C\xE0 chua \u0111\u1ECF m\u1EB7t r\u1ED3i. Ch\u1EAFc t\u1EE5i n\xF3 th\xEDch t\u1EDB.",
  "I told the pumpkin a joke. It did not laugh. It is very round and very serious.": "T\u1EDB k\u1EC3 chuy\u1EC7n c\u01B0\u1EDDi cho b\xED ng\xF4 nghe. N\xF3 kh\xF4ng c\u01B0\u1EDDi. N\xF3 tr\xF2n xoe v\xE0 nghi\xEAm t\xFAc l\u1EAFm.",
  "The robot waits and the plants get taller. We are both very patient!": "Ch\xFA robot ch\u1EDD cho c\xE2y cao th\xEAm. T\u1EE5i t\u1EDB \u0111\u1EC1u ki\xEAn nh\u1EABn l\u1EAFm nha!",
  "The robot lets the crops stand a while. Honestly, the garden looks lovely like this.": "Ch\xFA robot \u0111\u1EC3 c\xE2y \u0111\u1EE9ng th\xEAm m\u1ED9t l\xFAc. Th\u1EADt l\xF2ng th\xEC v\u01B0\u1EDDn nh\xECn nh\u01B0 v\u1EADy \u0111\u1EB9p gh\xEA.",
  "Radishes are the gossips of the garden. Everything pokes out sooner or later.": "C\u1EE7 c\u1EA3i l\xE0 d\xE2n bu\xF4n chuy\u1EC7n c\u1EE7a v\u01B0\u1EDDn. C\xE1i g\xEC c\u0169ng s\u1EDBm mu\u1ED9n l\xF2i ra.",
  "A full bed in the sun. I could stand here all afternoon. And I will.": "Lu\u1ED1ng \u0111\u1EA7y n\u1EAFng th\u1EBF n\xE0y, \u0111\u1EE9ng ng\u1EAFm c\u1EA3 bu\u1ED5i chi\u1EC1u c\u0169ng \u0111\u01B0\u1EE3c. M\xE0 m\xECnh s\u1EBD ng\u1EAFm th\u1EADt.",
  "The cow looked at me for a very long time. I think we are best friends now.": "B\xF2 nh\xECn t\u1EDB r\u1EA5t l\xE2u. Ch\u1EAFc gi\u1EDD t\u1EE5i t\u1EDB l\xE0 b\u1EA1n th\xE2n r\u1ED3i.",
  "Eggs are warm. Why are eggs warm? Were they hugged?": "Tr\u1EE9ng \u1EA5m gh\xEA. Sao tr\u1EE9ng l\u1EA1i \u1EA5m? C\xF3 ai \xF4m n\xF3 h\u1EA3?",
  "I counted the sheep to fall asleep, but they kept moving.": "T\u1EDB \u0111\u1EBFm c\u1EEBu cho d\u1EC5 ng\u1EE7, m\xE0 t\u1EE5i n\xF3 c\u1EE9 ch\u1EA1y lung tung.",
  "The pig has opinions about breakfast. Loud ones.": "Con heo c\xF3 \xFD ki\u1EBFn v\u1EC1 b\u1EEFa s\xE1ng. \xDD ki\u1EBFn to n\u1EEFa.",
  "Milk before sunrise, eggs after. Everyone has a schedule except the goat.": "S\u1EEFa tr\u01B0\u1EDBc b\xECnh minh, tr\u1EE9ng sau \u0111\xF3. Ai c\u0169ng c\xF3 l\u1ECBch, tr\u1EEB con d\xEA.",
  "Nothing makes a boss smile like a full basket. Look at that grin!": "Kh\xF4ng g\xEC l\xE0m s\u1EBFp c\u01B0\u1EDDi b\u1EB1ng gi\u1ECF \u0111\u1EA7y. Nh\xECn n\u1EE5 c\u01B0\u1EDDi k\xECa!",
  "I stirred the soup seven times. Seven is the lucky number for soup.": "T\u1EDB khu\u1EA5y s\xFAp b\u1EA3y l\u1EA7n. B\u1EA3y l\xE0 s\u1ED1 may m\u1EAFn c\u1EE7a m\xF3n s\xFAp.",
  "Is it sneezing or is it steam? The pot is being mysterious.": "N\u1ED3i h\u1EAFt x\xEC hay l\xE0 b\u1ED1c h\u01A1i v\u1EADy? N\xF3 b\xED \u1EA9n qu\xE1.",
  "I want to be a chef and a dragon. Dragons can toast the bread.": "T\u1EDB mu\u1ED1n l\xE0m \u0111\u1EA7u b\u1EBFp ki\xEAm r\u1ED3ng. R\u1ED3ng n\u01B0\u1EDBng b\xE1nh m\xEC \u0111\u01B0\u1EE3c m\xE0.",
  "Fresh from the garden today. The carrots practically jumped in the pot.": "H\xF4m nay rau t\u01B0\u01A1i t\u1EEB v\u01B0\u1EDDn. C\xE0 r\u1ED1t g\u1EA7n nh\u01B0 t\u1EF1 nh\u1EA3y v\xF4 n\u1ED3i.",
  "If the boss smells dinner, I have done my job.": "H\u1EC5 s\u1EBFp ng\u1EEDi th\u1EA5y m\xF9i b\u1EEFa t\u1ED1i l\xE0 m\xECnh l\xE0m tr\xF2n vi\u1EC7c r\u1ED3i.",
  "Salt is easy to add and impossible to take out. Ask my first stew.": "Mu\u1ED1i th\xEC th\xEAm d\u1EC5, b\u1EDBt th\xEC kh\xF4ng. H\u1ECFi m\xF3n h\u1EA7m \u0111\u1EA7u ti\xEAn c\u1EE7a m\xECnh th\xEC bi\u1EBFt.",
  "Who moved my cushion?": "Ai d\u1EDDi c\xE1i g\u1ED1i c\u1EE7a t\u1EDB v\u1EADy?",
  "It moved itself. It is a very brave cushion.": "N\xF3 t\u1EF1 d\u1EDDi \u0111\xF3. C\xE1i g\u1ED1i gan d\u1EA1 gh\xEA.",
  "Is the soup supposed to be purple?": "S\xFAp c\xF3 ph\u1EA3i m\xE0u t\xEDm kh\xF4ng v\u1EADy?",
  "It is a surprise soup. Surprise!": "S\xFAp b\u1EA5t ng\u1EDD \u0111\xF3. B\u1EA5t ng\u1EDD ch\u01B0a!",
  "Look, I made a hat!": "Nh\xECn n\xE8, t\u1EDB l\xE0m c\xE1i n\xF3n!",
  "That is a bucket. A lovely bucket.": "\u0110\xF3 l\xE0 c\xE1i x\xF4. M\u1ED9t c\xE1i x\xF4 \u0111\xE1ng y\xEAu.",
  "I cannot sleep. The dark is so loud.": "T\u1EDB kh\xF4ng ng\u1EE7 \u0111\u01B0\u1EE3c. B\xF3ng t\u1ED1i \u1ED3n qu\xE1.",
  "Count the garden plants. Slowly. They are standing very tall.": "\u0110\u1EBFm c\xE2y trong v\u01B0\u1EDDn \u0111i. T\u1EEB t\u1EEB th\xF4i. T\u1EE5i n\xF3 \u0111\u1EE9ng cao l\u1EAFm.",
  "Why is the duck wearing my towel?": "Sao con v\u1ECBt l\u1EA1i qu\u1EA5n kh\u0103n c\u1EE7a t\u1EDB?",
  "He is the boss of the bath. Obviously.": "N\xF3 l\xE0 s\u1EBFp c\u1EE7a nh\xE0 t\u1EAFm m\xE0. R\xF5 r\xE0ng v\u1EADy.",
  "What is the longest word you know?": "Ch\u1EEF d\xE0i nh\u1EA5t c\u1EADu bi\u1EBFt l\xE0 g\xEC?",
  "Dinner. It feels long when I wait for it.": "B\u1EEFa t\u1ED1i. Ch\u1EDD n\xF3 th\u1EA5y d\xE0i gh\xEA.",
  "Boss! Boss! I did something! I forgot what. But it was big!": "S\u1EBFp \u01A1i! S\u1EBFp! T\u1EDB l\xE0m \u0111\u01B0\u1EE3c m\u1ED9t chuy\u1EC7n! Qu\xEAn m\u1EA5t l\xE0 g\xEC r\u1ED3i. M\xE0 to l\u1EAFm!",
  "Boss, can you carry me? Only a little bit. To the moon.": "S\u1EBFp \u01A1i, b\u1EBF t\u1EDB \u0111\u01B0\u1EE3c kh\xF4ng? M\u1ED9t x\xEDu th\xF4i. L\xEAn t\u1EDBi m\u1EB7t tr\u0103ng.",
  "The boss is back! Did you bring snacks? Even a leaf would do.": "S\u1EBFp v\u1EC1 r\u1ED3i! C\xF3 mang \u0111\u1ED3 \u0103n v\u1EB7t kh\xF4ng? M\u1ED9t c\xE1i l\xE1 c\u0169ng \u0111\u01B0\u1EE3c.",
  "Boss, your boots are very big. Can I wear one as a boat?": "S\u1EBFp \u01A1i, gi\xE0y s\u1EBFp to qu\xE1. T\u1EDB l\xE0m thuy\u1EC1n \u0111\u01B0\u1EE3c kh\xF4ng?",
  "I tidied up! Everything is in one big pile. Very organised.": "T\u1EDB d\u1ECDn d\u1EB9p r\u1ED3i! M\u1ECDi th\u1EE9 n\u1EB1m trong m\u1ED9t \u0111\u1ED1ng to. Ng\u0103n n\u1EAFp l\u1EAFm.",
  "Boss, you are the bestest. Please do not tell the others I said so.": "S\u1EBFp l\xE0 s\u1ED1 m\u1ED9t lu\xF4n. \u0110\u1EEBng n\xF3i v\u1EDBi m\u1EA5y b\u1EA1n kh\xE1c l\xE0 t\u1EDB n\xF3i nha.",
  "Shh, the boss is here. Everybody look busy! Hold this spoon!": "Su\u1EF5t, s\u1EBFp t\u1EDBi r\u1ED3i. C\u1EA3 nh\xE0 gi\u1EA3 v\u1EDD b\u1EADn \u0111i! C\u1EA7m c\xE1i mu\u1ED7ng n\xE0y!",
  "Boss, I grew an entire millimetre. Measure me!": "S\u1EBFp \u01A1i, t\u1EDB cao th\xEAm c\u1EA3 m\u1ED9t ly r\u1ED3i. \u0110o t\u1EDB \u0111i!",
  "Welcome home, boss. The house behaved. Mostly. The kettle sulked.": "S\u1EBFp v\u1EC1 nh\xE0 r\u1ED3i. Nh\xE0 c\u1EEDa ngoan c\u1EA3. G\u1EA7n nh\u01B0 v\u1EADy. Ch\u1EC9 c\xF3 \u1EA5m n\u01B0\u1EDBc h\u01A1i d\u1ED7i.",
  "Boss, the garden is thriving. I would say it is because of me, but the robot is listening.": "S\u1EBFp \u01A1i, v\u01B0\u1EDDn xanh t\u1ED1t l\u1EAFm. M\xECnh mu\u1ED1n n\xF3i nh\u1EDD m\xECnh, m\xE0 ch\xFA robot \u0111ang nghe.",
  "Good to see you, boss. Dinner in ten minutes. Or twenty. Cooking is not an exact science.": "M\u1EEBng s\u1EBFp v\u1EC1. M\u01B0\u1EDDi ph\xFAt n\u1EEFa \u0103n c\u01A1m. Ho\u1EB7c hai m\u01B0\u01A1i. N\u1EA5u \u0103n \u0111\xE2u ph\u1EA3i khoa h\u1ECDc ch\xEDnh x\xE1c.",
  "Boss, you have leaves in your hair. It suits you, honestly.": "S\u1EBFp \u01A1i, t\xF3c s\u1EBFp d\xEDnh l\xE1 k\xECa. M\xE0 n\xF3i th\u1EADt, h\u1EE3p l\u1EAFm.",
  "We saved you the comfy seat. Well, we argued over it first.": "T\u1EE5i m\xECnh gi\u1EEF gh\u1EBF \xEAm cho s\u1EBFp r\u1ED3i. D\u0129 nhi\xEAn l\xE0 c\xE3i nhau tr\u01B0\u1EDBc \u0111\xE3.",
  "Everything is under control, boss. Do not look behind the sofa.": "M\u1ECDi th\u1EE9 \u0111\u1EC1u \u1ED5n, s\u1EBFp. \u0110\u1EEBng nh\xECn sau c\xE1i sofa nha.",
  "The crops are standing tall just for you, boss. They practised all morning.": "C\xE2y tr\u1ED3ng \u0111\u1EE9ng th\u1EB3ng t\u1EAFp ch\u1EC9 \u0111\u1EC3 ch\xE0o s\u1EBFp. T\u1EE5i n\xF3 t\u1EADp c\u1EA3 bu\u1ED5i s\xE1ng \u0111\xF3.",
  "Another day, another basket. You work too hard, boss. Sit. Tea.": "L\u1EA1i m\u1ED9t ng\xE0y m\u1ED9t gi\u1ECF n\u1EEFa. S\u1EBFp l\xE0m vi\u1EC7c v\u1EA5t v\u1EA3 qu\xE1. Ng\u1ED3i xu\u1ED1ng u\u1ED1ng tr\xE0 \u0111i.",
  "Home sweet home. Sweeter with snacks.": "Nh\xE0 l\xE0 nh\u1EA5t. C\xF3 \u0111\u1ED3 \u0103n v\u1EB7t th\xEC nh\u1EA5t n\u1EEFa.",
  "Right. Where did I leave my sword? And my keys? And my dignity?": "\u1EEAm. M\xECnh \u0111\u1EC3 ki\u1EBFm \u0111\xE2u r\u1ED3i nh\u1EC9? Ch\xECa kho\xE1 n\u1EEFa? V\xE0 c\u1EA3 ph\u1EA9m gi\xE1 n\u1EEFa?",
  "Being the boss mostly means knowing where the biscuits are.": "L\xE0m s\u1EBFp ch\u1EE7 y\u1EBFu l\xE0 bi\u1EBFt b\xE1nh quy \u0111\u1EC3 \u0111\xE2u.",
  "I wonder if the pumpkins are plotting something.": "Kh\xF4ng bi\u1EBFt b\xED ng\xF4 c\xF3 \u0111ang \xE2m m\u01B0u g\xEC kh\xF4ng.",
  "Everyone is working so hard. I will supervise. From the sofa.": "M\u1ECDi ng\u01B0\u1EDDi l\xE0m vi\u1EC7c ch\u0103m ch\u1EC9 gh\xEA. M\xECnh s\u1EBD gi\xE1m s\xE1t. T\u1EEB gh\u1EBF sofa.",
  "The garden looks great. Let the plants show off a little longer.": "V\u01B0\u1EDDn \u0111\u1EB9p qu\xE1. C\u1EE9 \u0111\u1EC3 c\xE2y khoe th\xEAm ch\xFAt n\u1EEFa.",
  "Note to self: wipe the boots. Second note: ignore the first note.": "Nh\u1EAFc m\xECnh: lau gi\xE0y. Nh\u1EAFc th\xEAm: k\u1EC7 l\u1EDDi nh\u1EAFc \u0111\u1EA7u.",
  "A little tea, a little quiet, a little nap. In that order.": "M\u1ED9t ch\xFAt tr\xE0, m\u1ED9t ch\xFAt y\xEAn t\u0129nh, m\u1ED9t ch\xFAt ng\u1EE7 tr\u01B0a. Theo th\u1EE9 t\u1EF1 \u0111\xF3."
};

// ../../../../source/repos/cute_game/src/friend-lines-more.ts
var MORE_LINES = {
  HARVEST: [
    ["Every big harvest started as one tiny seed and a lot of patience.", "M\u1ED7i m\xF9a b\u1ED9i thu \u0111\u1EC1u b\u1EAFt \u0111\u1EA7u t\u1EEB m\u1ED9t h\u1EA1t gi\u1ED1ng b\xE9 x\xEDu v\xE0 th\u1EADt nhi\u1EC1u ki\xEAn nh\u1EABn."],
    ["This is what happens when you do a little every day.", "\u0110\xE2y l\xE0 \u0111i\u1EC1u x\u1EA3y ra khi m\u1ED7i ng\xE0y m\xECnh l\xE0m m\u1ED9t ch\xFAt."],
    ["I think this one is smiling at me. Or it is just a bruise.", "M\xECnh ngh\u0129 qu\u1EA3 n\xE0y \u0111ang c\u01B0\u1EDDi v\u1EDBi m\xECnh. Ho\u1EB7c ch\u1EC9 l\xE0 v\u1EBFt th\xE2m th\xF4i."],
    ["Look how far a seed can go. Makes me believe in myself.", "Xem h\u1EA1t gi\u1ED1ng \u0111i \u0111\u01B0\u1EE3c xa th\u1EBF n\xE0o. L\xE0m m\xECnh tin v\xE0o b\u1EA3n th\xE2n h\u01A1n."],
    ["Harvest done! Time to dream up something even bigger.", "Thu ho\u1EA1ch xong! Gi\u1EDD m\u01A1 m\u1ED9t \u0111i\u1EC1u c\xF2n to h\u01A1n n\xE0o."],
    ["Plants do not rush, and they still get there. Wise, right?", "C\xE2y kh\xF4ng v\u1ED9i m\xE0 v\u1EABn t\u1EDBi \u0111\xEDch. Th\xF4ng th\xE1i ch\u01B0a?"]
  ],
  PLANT: [
    ["Every garden is a little promise that tomorrow will be good.", "M\u1ED7i khu v\u01B0\u1EDDn l\xE0 m\u1ED9t l\u1EDDi h\u1EE9a nh\u1ECF r\u1EB1ng ng\xE0y mai s\u1EBD t\u1ED1t \u0111\u1EB9p."],
    ["Small seed, big dreams. We have a lot in common.", "H\u1EA1t nh\u1ECF, m\u01A1 \u01B0\u1EDBc l\u1EDBn. B\u1ECDn m\xECnh gi\u1ED1ng nhau gh\xEA."],
    ["Go on, little seed. The sun believes in you.", "N\xE0o, h\u1EA1t nh\u1ECF. M\u1EB7t tr\u1EDDi tin \u1EDF b\u1EA1n \u0111\xF3."],
    ["Planting is just hoping, with dirt on your hands.", "Gieo tr\u1ED3ng ch\xEDnh l\xE0 hy v\u1ECDng, v\u1EDBi \u0111\xF4i tay l\u1EA5m \u0111\u1EA5t."],
    ["I wonder what it will become. That is the fun part.", "Kh\xF4ng bi\u1EBFt n\xF3 s\u1EBD th\xE0nh g\xEC nh\u1EC9. Ch\u1ED7 vui nh\u1EA5t ch\xEDnh l\xE0 \u0111\xF3."],
    ["Do not worry, seed. I will not dig you up to check. Much.", "\u0110\u1EEBng lo, h\u1EA1t \u01A1i. M\xECnh s\u1EBD kh\xF4ng \u0111\xE0o l\xEAn xem \u0111\xE2u. Ch\u1EAFc v\u1EADy."]
  ],
  COLLECT: [
    ["Look at all this. Hard work really does add up.", "Nh\xECn b\u1EA5y nhi\xEAu n\xE0y. Ch\u0103m ch\u1EC9 \u0111\xFAng l\xE0 c\u1ED9ng d\u1ED3n th\u1EADt."],
    ["Collecting is the happiest chore. Nobody can argue.", "Thu gom l\xE0 vi\u1EC7c nh\xE0 vui nh\u1EA5t. Ai c\xE3i th\xEC th\xF4i."],
    ["The animals did the hard part. I just say thank you.", "C\xE1c b\u1EA1n th\xFA l\xE0m ph\u1EA7n kh\xF3. M\xECnh ch\u1EC9 vi\u1EC7c c\u1EA3m \u01A1n."],
    ["One at a time, and suddenly the basket is full. Funny how that works.", "T\u1EEBng c\xE1i m\u1ED9t, th\u1EBF l\xE0 gi\u1ECF \u0111\u1EA7y. L\u1EA1 th\u1EADt."],
    ["A good day starts with a little gratitude. Thank you, hens!", "M\u1ED9t ng\xE0y t\u1ED1t l\xE0nh b\u1EAFt \u0111\u1EA7u b\u1EB1ng ch\xFAt bi\u1EBFt \u01A1n. C\u1EA3m \u01A1n m\u1EA5y b\xE0 g\xE0!"],
    ["I was going to count them, but I got distracted by cuteness.", "M\xECnh \u0111\u1ECBnh \u0111\u1EBFm, nh\u01B0ng b\u1ECB ph\xE2n t\xE2m v\xEC d\u1EC5 th\u01B0\u01A1ng qu\xE1."]
  ],
  FEED: [
    ["Eat well, grow strong, and keep your dreams big.", "\u0102n ngon, l\u1EDBn kh\u1ECFe, v\xE0 c\u1EE9 m\u01A1 th\u1EADt l\u1EDBn nh\xE9."],
    ["Nobody works well on an empty tummy. Not even me.", "Ch\u1EB3ng ai l\xE0m vi\u1EC7c t\u1ED1t khi b\u1EE5ng \u0111\xF3i. M\xECnh c\u0169ng v\u1EADy."],
    ["Slow down, there is plenty! Chew with your mouth closed. Please.", "T\u1EEB t\u1EEB th\xF4i, c\xF2n nhi\u1EC1u m\xE0! Nhai mi\u1EC7ng kh\xE9p l\u1EA1i nh\xE9. L\xE0m \u01A1n."],
    ["A little care every day makes everything flourish.", "M\u1ED9t ch\xFAt quan t\xE2m m\u1ED7i ng\xE0y l\xE0m m\u1ECDi th\u1EE9 n\u1EDF r\u1ED9."],
    ["You are doing great, little one. Keep going.", "B\u1EA1n gi\u1ECFi l\u1EAFm, b\xE9 \u01A1i. C\u1EE9 ti\u1EBFp t\u1EE5c nh\xE9."]
  ],
  COOK: [
    ["Cooking is just art you can eat. Beautiful, right?", "N\u1EA5u \u0103n ch\u1EC9 l\xE0 ngh\u1EC7 thu\u1EADt \u0103n \u0111\u01B0\u1EE3c th\xF4i. \u0110\u1EB9p ch\u01B0a?"],
    ["A pinch of this, a pinch of that, and a lot of love.", "M\u1ED9t nh\xFAm n\xE0y, m\u1ED9t nh\xFAm kia, v\xE0 th\u1EADt nhi\u1EC1u y\xEAu th\u01B0\u01A1ng."],
    ["I got a new idea for a recipe. It might be brilliant. Or soup.", "M\xECnh c\xF3 \xFD t\u01B0\u1EDFng c\xF4ng th\u1EE9c m\u1EDBi. C\xF3 th\u1EC3 r\u1EA5t tuy\u1EC7t. Ho\u1EB7c th\xE0nh m\xF3n s\xFAp."],
    ["Great meals begin with a little curiosity. What if we add cheese?", "B\u1EEFa ngon b\u1EAFt \u0111\u1EA7u t\u1EEB ch\xFAt t\xF2 m\xF2. Th\xEAm ph\xF4 mai th\xEC sao nh\u1EC9?"],
    ["Mistakes make the best flavours. That is my excuse, anyway.", "L\u1EE1 tay l\u1EA1i ra v\u1ECB ngon nh\u1EA5t. D\xF9 sao \u0111\xF3 l\xE0 l\xFD do c\u1EE7a m\xECnh."],
    ["Cooking for you makes my whole day feel meaningful.", "N\u1EA5u \u0103n cho b\u1EA1n l\xE0m c\u1EA3 ng\xE0y c\u1EE7a m\xECnh th\u1EADt \xFD ngh\u0129a."]
  ],
  NICE: [
    ["You inspire me every single day, boss.", "Ng\xE0y n\xE0o b\u1EA1n c\u0169ng truy\u1EC1n c\u1EA3m h\u1EE9ng cho m\xECnh, s\u1EBFp \u1EA1."],
    ["Because of you, this garden feels like a dream come true.", "Nh\u1EDD c\xF3 b\u1EA1n, khu v\u01B0\u1EDDn n\xE0y nh\u01B0 gi\u1EA5c m\u01A1 th\xE0nh s\u1EF1 th\u1EADt."],
    ["Boss, your kindness grows more than any crop.", "S\u1EBFp \u01A1i, l\xF2ng t\u1ED1t c\u1EE7a b\u1EA1n l\u1EDBn h\u01A1n m\u1ECDi lo\u1EA1i c\xE2y."],
    ["I woke up with an idea, and then I forgot it. Classic me.", "M\xECnh t\u1EC9nh d\u1EADy v\u1EDBi m\u1ED9t \xFD t\u01B0\u1EDFng, r\u1ED3i qu\xEAn m\u1EA5t. \u0110\xFAng ki\u1EC3u m\xECnh."],
    ["Keep trying new things. That is how gardens, and people, bloom.", "C\u1EE9 th\u1EED \u0111i\u1EC1u m\u1EDBi nh\xE9. V\u01B0\u1EDDn v\xE0 con ng\u01B0\u1EDDi \u0111\u1EC1u n\u1EDF hoa nh\u01B0 v\u1EADy."],
    ["You make hard work feel like play. How do you do that?", "B\u1EA1n bi\u1EBFn vi\u1EC7c n\u1EB7ng th\xE0nh tr\xF2 ch\u01A1i. L\xE0m sao v\u1EADy?"],
    ["Whenever I feel small, I remember how big the trees get.", "M\u1ED7i khi th\u1EA5y m\xECnh nh\u1ECF b\xE9, m\xECnh nh\u1EDB c\xE2y c\u0169ng l\u1EDBn l\xEAn \u0111\u01B0\u1EE3c."],
    ["Thank you for believing in us. It means the world.", "C\u1EA3m \u01A1n v\xEC \u0111\xE3 tin t\u1EE5i m\xECnh. \u0110i\u1EC1u \u0111\xF3 qu\xFD l\u1EAFm."],
    ["Be proud of today, boss. Small steps count too.", "H\xE3y t\u1EF1 h\xE0o v\u1EC1 h\xF4m nay, s\u1EBFp \u1EA1. B\u01B0\u1EDBc nh\u1ECF c\u0169ng t\xEDnh."],
    ["I have a great idea! It is a secret. I forgot what it is.", "M\xECnh c\xF3 \xFD t\u01B0\u1EDFng tuy\u1EC7t l\u1EAFm! L\xE0 b\xED m\u1EADt. M\xE0 m\xECnh qu\xEAn m\u1EA5t r\u1ED3i."],
    ["Some days the best idea is a nap. I am only half joking.", "C\xF3 h\xF4m \xFD t\u01B0\u1EDFng hay nh\u1EA5t l\xE0 m\u1ED9t gi\u1EA5c ng\u1EE7 tr\u01B0a. M\xECnh ch\u1EC9 \u0111\xF9a m\u1ED9t n\u1EEDa."],
    ["You make this place feel like home. Thank you, boss.", "B\u1EA1n l\xE0m n\u01A1i n\xE0y nh\u01B0 m\u1ED9t m\xE1i nh\xE0. C\u1EA3m \u01A1n s\u1EBFp."]
  ],
  HOME: [
    ["Rest is part of the work. Even the soil needs a break.", "Ngh\u1EC9 ng\u01A1i c\u0169ng l\xE0 m\u1ED9t ph\u1EA7n c\xF4ng vi\u1EC7c. \u0110\u1EA5t c\u0169ng c\u1EA7n ngh\u1EC9 m\xE0."],
    ["Good ideas love quiet moments. Time to find some.", "\xDD t\u01B0\u1EDFng hay th\xEDch nh\u1EEFng l\xFAc y\xEAn t\u0129nh. \u0110i t\xECm ch\xFAt th\xF4i."],
    ["I will think about tomorrow by the fire. Big plans.", "M\xECnh s\u1EBD ngh\u0129 v\u1EC1 ng\xE0y mai b\xEAn l\xF2 s\u01B0\u1EDFi. K\u1EBF ho\u1EA1ch l\u1EDBn \u0111\u1EA5y."],
    ["A cup of tea and a good daydream. Perfect.", "M\u1ED9t t\xE1ch tr\xE0 v\xE0 m\u1ED9t gi\u1EA5c m\u01A1 ng\xE0y. Ho\xE0n h\u1EA3o."],
    ["I recharge indoors, like a very polite battery.", "M\xECnh s\u1EA1c pin trong nh\xE0, nh\u01B0 m\u1ED9t c\u1EE5c pin r\u1EA5t l\u1ECBch s\u1EF1."],
    ["Home is where the best inspiration finds me.", "Nh\xE0 l\xE0 n\u01A1i c\u1EA3m h\u1EE9ng hay nh\u1EA5t t\xECm \u0111\u1EBFn m\xECnh."]
  ],
  OUTFIT: [
    ["Dress for the day you want. Today I want to be fabulous.", "M\u1EB7c cho ng\xE0y m\xECnh mu\u1ED1n. H\xF4m nay m\xECnh mu\u1ED1n th\u1EADt l\u1ED9ng l\u1EABy."],
    ["A new look gives me new ideas. Funny how that works.", "Di\u1EC7n m\u1EA1o m\u1EDBi cho m\xECnh \xFD t\u01B0\u1EDFng m\u1EDBi. L\u1EA1 th\u1EADt."],
    ["Confidence is the best accessory. And a nice hat.", "T\u1EF1 tin l\xE0 ph\u1EE5 ki\u1EC7n \u0111\u1EB9p nh\u1EA5t. Th\xEAm c\xE1i m\u0169 xinh n\u1EEFa."],
    ["Look at me! I can be anything. Today: a chef in style.", "Nh\xECn m\xECnh n\xE8! M\xECnh c\xF3 th\u1EC3 l\xE0 b\u1EA5t c\u1EE9 ai. H\xF4m nay: \u0111\u1EA7u b\u1EBFp s\xE0nh \u0111i\u1EC7u."],
    ["Every outfit is a little story. This one is a happy one.", "M\u1ED7i b\u1ED9 \u0111\u1ED3 l\xE0 m\u1ED9t c\xE2u chuy\u1EC7n nh\u1ECF. B\u1ED9 n\xE0y vui l\u1EAFm."]
  ]
};

// ../../../../source/repos/cute_game/src/locales/vi-friend-lines.ts
var VI_FRIEND_LINES = {
  ...Object.fromEntries(Object.values(MORE_LINES).flat().map(([en, vi]) => [en, vi])),
  "Look at that one! Big and proud.": "Nh\xECn qu\u1EA3 n\xE0y n\xE8! To v\xE0 t\u1EF1 h\xE0o gh\xEA.",
  "Into the basket you go, little friend.": "V\xE0o gi\u1ECF n\xE0o, b\u1EA1n nh\u1ECF.",
  "Ripe at last. Good things come to those who wait five minutes.": "Ch\xEDn r\u1ED3i! Ch\u1EDD n\u0103m ph\xFAt l\xE0 x\u1EE9ng \u0111\xE1ng.",
  "This one practically jumped into my hand.": "C\xE2y n\xE0y g\u1EA7n nh\u01B0 t\u1EF1 nh\u1EA3y v\xE0o tay m\xECnh.",
  "Another crop for the boss. I am on a roll!": "Th\xEAm m\u1ED9t m\u1EDB cho s\u1EBFp. M\xECnh \u0111ang h\u0103ng l\u1EAFm!",
  "Smells like sunshine and soil. Lovely.": "Th\u01A1m m\xF9i n\u1EAFng v\xE0 m\xF9i \u0111\u1EA5t. D\u1EC5 ch\u1ECBu gh\xEA.",
  "Sorry, plant. Your holiday is over.": "Xin l\u1ED7i c\xE2y nha, h\u1EBFt k\u1EF3 ngh\u1EC9 r\u1ED3i.",
  "Heavy! Somebody has been eating their vitamins.": "N\u1EB7ng tay gh\xEA! C\xE2y n\xE0y u\u1ED1ng \u0111\u1EE7 vitamin r\u1ED3i.",
  "I only squeezed a little. Promise.": "M\xECnh ch\u1EC9 b\xF3p nh\u1EB9 th\xF4i. H\u1EE9a \u0111\xF3.",
  "One more for the pile. The pile is getting tall.": "Th\xEAm m\u1ED9t c\xE1i n\u1EEFa. \u0110\u1ED1ng n\xE0y cao d\u1EA7n r\u1ED3i.",
  "That was the plumpest one all week.": "\u0110\xE2y l\xE0 qu\u1EA3 m\u0169m m\u0129m nh\u1EA5t tu\u1EA7n lu\xF4n.",
  "Snip, pull, done. Easy as pie. Pie is next, actually.": "C\u1EAFt, nh\u1ED5, xong. D\u1EC5 nh\u01B0 \u0103n b\xE1nh. \xC0 m\xE0 b\xE1nh l\xE0 b\u01B0\u1EDBc ti\u1EBFp theo.",
  "The garden thanks you for the sunshine, and me for the pulling.": "V\u01B0\u1EDDn c\u1EA3m \u01A1n n\u1EAFng, c\xF2n m\xECnh c\u1EA3m \u01A1n v\xEC \u0111\u01B0\u1EE3c nh\u1ED5.",
  "Wow, the roots go all the way down. Impressive.": "\xD4i, r\u1EC5 \u0103n s\xE2u gh\xEA. \u1EA4n t\u01B0\u1EE3ng th\u1EADt.",
  "This one is going straight to the top shelf.": "Qu\u1EA3 n\xE0y l\xEAn k\u1EC7 tr\xEAn c\xF9ng lu\xF4n.",
  "Did that carrot just wink at me?": "C\u1EE7 c\xE0 r\u1ED1t v\u1EEBa nh\xE1y m\u1EAFt v\u1EDBi m\xECnh h\u1EA3?",
  "Harvest time! My favourite time. After lunch time.": "Gi\u1EDD thu ho\u1EA1ch! Gi\u1EDD m\xECnh th\xEDch nh\u1EA5t. Sau gi\u1EDD \u0103n tr\u01B0a.",
  "Careful, careful... got it! Not a single leaf torn.": "T\u1EEB t\u1EEB n\xE0o... \u0111\u01B0\u1EE3c r\u1ED3i! Kh\xF4ng r\xE1ch chi\u1EBFc l\xE1 n\xE0o.",
  "The garden is generous today.": "H\xF4m nay v\u01B0\u1EDDn h\xE0o ph\xF3ng gh\xEA.",
  "Fresh as a daisy, and much tastier.": "T\u01B0\u01A1i nh\u01B0 hoa c\xFAc, m\xE0 ngon h\u01A1n nhi\u1EC1u.",
  "Tuck in, little seed. Sweet dreams.": "Ng\u1EE7 ngon nha h\u1EA1t gi\u1ED1ng b\xE9 nh\u1ECF.",
  "Grow tall, grow strong, grow quickly.": "L\u1EDBn th\u1EADt cao, th\u1EADt kho\u1EBB, v\xE0 l\u1EDBn nhanh nha.",
  "A little water and a little hope. Done.": "Ch\xFAt n\u01B0\u1EDBc, ch\xFAt hy v\u1ECDng. Xong.",
  "Plant it, pat it, and wait five whole minutes.": "Tr\u1ED3ng, v\u1ED7 nh\u1EB9, r\u1ED3i ch\u1EDD n\u0103m ph\xFAt.",
  "Not too deep, not too shallow. Just right.": "Kh\xF4ng s\xE2u qu\xE1, kh\xF4ng n\xF4ng qu\xE1. V\u1EEBa v\u1EB7n.",
  "Welcome to the garden, new neighbour.": "Ch\xE0o m\u1EEBng h\xE0ng x\xF3m m\u1EDBi \u0111\u1EBFn v\u01B0\u1EDDn.",
  "I whispered a secret to it. It will not tell.": "M\xECnh th\xEC th\u1EA7m b\xED m\u1EADt cho n\xF3. N\xF3 s\u1EBD kh\xF4ng k\u1EC3 ai \u0111\xE2u.",
  "Another bed full of promises.": "Th\xEAm m\u1ED9t lu\u1ED1ng \u0111\u1EA7y h\u1EE9a h\u1EB9n.",
  "Do not peek, little seed. Growing takes time.": "\u0110\u1EEBng l\xF3 l\xEAn v\u1ED9i nha h\u1EA1t nh\u1ECF. L\u1EDBn c\u1EA7n th\u1EDDi gian.",
  "Snug as a bug in a bed.": "\u1EA4m \xE1p nh\u01B0 con b\u1ECD trong ch\u0103n.",
  "That bed looks happy now.": "Lu\u1ED1ng \u0111\xF3 tr\xF4ng vui r\u1ED3i n\xE8.",
  "Plant, water, repeat. My kind of poetry.": "Tr\u1ED3ng, t\u01B0\u1EDBi, l\u1EB7p l\u1EA1i. \u0110\xF3 l\xE0 th\u01A1 c\u1EE7a m\xECnh.",
  "Thank you, hens! Six eggs, all warm.": "C\u1EA3m \u01A1n m\u1EA5y c\xF4 g\xE0! S\xE1u qu\u1EA3 tr\u1EE9ng, c\xF2n \u1EA5m n\xE8.",
  "Gently now... the cow is watching me.": "Nh\u1EB9 tay n\xE0o... b\xF2 \u0111ang nh\xECn m\xECnh k\xECa.",
  "Fresh milk, still steaming. Best job ever.": "S\u1EEFa t\u01B0\u01A1i c\xF2n b\u1ED1c h\u01A1i. C\xF4ng vi\u1EC7c tuy\u1EC7t nh\u1EA5t lu\xF4n.",
  "The duck gave me a very serious look and an egg.": "Con v\u1ECBt nh\xECn m\xECnh r\u1EA5t nghi\xEAm r\u1ED3i \u0111\u01B0a m\u1ED9t qu\u1EA3 tr\u1EE9ng.",
  "Look at the size of this one!": "Nh\xECn c\u1EE1 qu\u1EA3 n\xE0y \u0111i!",
  "Truffles! The pig has a gift for finding them.": "N\u1EA5m c\u1EE5c! Con heo c\xF3 t\xE0i t\xECm ch\xFAng.",
  "Thank you, friend. Same time tomorrow?": "C\u1EA3m \u01A1n b\u1EA1n nha. Mai gi\u1EDD n\xE0y n\u1EEFa nh\xE9?",
  "Careful, careful, do not drop it. Do not drop it.": "C\u1EA9n th\u1EADn, c\u1EA9n th\u1EADn, \u0111\u1EEBng l\xE0m r\u01A1i. \u0110\u1EEBng l\xE0m r\u01A1i.",
  "The pen is spotless and the baskets are full.": "Chu\u1ED3ng s\u1EA1ch bong v\xE0 gi\u1ECF \u0111\u1EA7y \u1EAFp.",
  "I hummed a tune and the hens joined in. Sort of.": "M\xECnh ng\xE2n nga m\u1ED9t b\xE0i, m\u1EA5y c\xF4 g\xE0 h\xE1t theo. C\u0169ng g\u1EA7n gi\u1ED1ng.",
  "One for the boss, one for the chest, none for me.": "M\u1ED9t cho s\u1EBFp, m\u1ED9t cho r\u01B0\u01A1ng, kh\xF4ng c\xE1i n\xE0o cho m\xECnh.",
  "Hello, little one. Yes, you are all very good animals.": "Ch\xE0o b\xE9 nha. \u1EEA, t\u1EA5t c\u1EA3 \u0111\u1EC1u l\xE0 nh\u1EEFng b\xE9 ngoan.",
  "Warm eggs on a cold day. Joy!": "Tr\u1EE9ng \u1EA5m trong ng\xE0y l\u1EA1nh. Vui gh\xEA!",
  "That cow is the queen of the barn, I am sure of it.": "Con b\xF2 \u0111\xF3 l\xE0 n\u1EEF ho\xE0ng chu\u1ED3ng tr\u1EA1i, m\xECnh ch\u1EAFc lu\xF4n.",
  "Collected, counted and cuddled.": "Thu xong, \u0111\u1EBFm xong v\xE0 \xF4m xong.",
  "Not a single crack in this batch.": "M\u1EBB n\xE0y kh\xF4ng n\u1EE9t qu\u1EA3 n\xE0o.",
  "The goose... I mean the duck... says hello.": "Con ng\u1ED7ng... \xE0 nh\u1EA7m, con v\u1ECBt... ch\xE0o b\u1EA1n.",
  "Everyone is fed, everyone is happy.": "Ai c\u0169ng no, ai c\u0169ng vui.",
  "I will be back with the bucket soon.": "L\xE1t n\u1EEFa m\xECnh quay l\u1EA1i v\u1EDBi c\xE1i x\xF4.",
  "Farm life is the good life.": "\u0110\u1EDDi n\xF4ng tr\u1EA1i l\xE0 \u0111\u1EDDi \u0111\u1EB9p.",
  "Lunch is served, everybody!": "B\u1EEFa tr\u01B0a \u0111\u1EBFn r\u1ED3i, c\u1EA3 nh\xE0 \u01A1i!",
  "Slowly, slowly, there is plenty for all.": "T\u1EEB t\u1EEB th\xF4i, \u0111\u1EE7 cho t\u1EA5t c\u1EA3 m\xE0.",
  "Eat up, you lovely things.": "\u0102n \u0111i n\xE0o, m\u1EA5y b\xE9 \u0111\xE1ng y\xEAu.",
  "No pushing! The cow goes first.": "Kh\xF4ng chen l\u1EA5n! B\xF2 \u0103n tr\u01B0\u1EDBc.",
  "The pig has finished already and is looking at mine.": "Con heo \u0103n xong r\u1ED3i v\xE0 \u0111ang nh\xECn ph\u1EA7n c\u1EE7a m\xECnh.",
  "Crunch crunch crunch. The best sound.": "R\u1ED9p r\u1ED9p r\u1ED9p. \xC2m thanh hay nh\u1EA5t.",
  "A full tummy makes a happy animal.": "B\u1EE5ng no th\xEC th\xFA vui.",
  "I always leave one for the boss.": "M\xECnh lu\xF4n ch\u1EEBa m\u1ED9t ph\u1EA7n cho s\u1EBFp.",
  "Nom nom. Wait, that was supposed to be the animals.": "Ngon qu\xE1. Khoan, c\xE1i n\xE0y l\xE0 c\u1EE7a m\u1EA5y b\xE9 m\xE0.",
  "Everyone gets a share. Fair and square.": "Ai c\u0169ng c\xF3 ph\u1EA7n. C\xF4ng b\u1EB1ng nha.",
  "Look at them go! Eating champions.": "Nh\xECn t\u1EE5i n\xF3 \u0103n k\xECa! Nh\xE0 v\xF4 \u0111\u1ECBch \u0103n u\u1ED1ng.",
  "Fed, watered and fluffed.": "Cho \u0103n, cho u\u1ED1ng v\xE0 vu\u1ED1t ve xong.",
  "Lovely, that goes straight in the pot.": "Ngon qu\xE1, c\xE1i n\xE0y v\xE0o n\u1ED3i lu\xF4n.",
  "Ingredients, assemble!": "Nguy\xEAn li\u1EC7u, t\u1EADp h\u1EE3p!",
  "I can already taste tonight's dinner.": "M\xECnh \u0111\xE3 n\u1EBFm \u0111\u01B0\u1EE3c b\u1EEFa t\u1ED1i nay r\u1ED3i.",
  "Fresh and crisp. Chef's kiss.": "T\u01B0\u01A1i gi\xF2n. H\xF4n tay \u0111\u1EA7u b\u1EBFp m\u1ED9t c\xE1i.",
  "This will go perfectly with a little salt.": "C\xE1i n\xE0y h\u1EE3p v\u1EDBi ch\xFAt mu\u1ED1i l\u1EAFm.",
  "Half for the pot, half for the boss. Fair deal.": "N\u1EEDa cho n\u1ED3i, n\u1EEDa cho s\u1EBFp. Chia \u0111\u1EC1u nha.",
  "If it smells this good raw, imagine cooked.": "S\u1ED1ng m\xE0 th\u01A1m v\u1EA7y, ch\xEDn th\xEC th\u01A1m c\u1EE1 n\xE0o.",
  "Soup, stew or pie? Decisions, decisions.": "S\xFAp, h\u1EA7m hay b\xE1nh? Kh\xF3 ch\u1ECDn gh\xEA.",
  "My apron is already full of treasure.": "T\u1EA1p d\u1EC1 m\xECnh \u0111\u1EA7y kho b\xE1u r\u1ED3i.",
  "Do not tell the pot I am late. It gets grumpy.": "\u0110\u1EEBng n\xF3i v\u1EDBi c\xE1i n\u1ED3i l\xE0 m\xECnh tr\u1EC5 nha. N\xF3 c\xE1u l\u1EAFm.",
  "A cook never wastes a good ingredient.": "\u0110\u1EA7u b\u1EBFp kh\xF4ng bao gi\u1EDD ph\xED nguy\xEAn li\u1EC7u ngon.",
  "Cooking is mostly choosing the right things to eat on the way.": "N\u1EA5u \u0103n ch\u1EE7 y\u1EBFu l\xE0 ch\u1ECDn \u0111\xFAng th\u1EE9 \u0111\u1EC3 n\u1EBFm tr\xEAn \u0111\u01B0\u1EDDng.",
  "Mmm, one tiny taste test. For science.": "Mmm, n\u1EBFm th\u1EED x\xEDu th\xF4i. V\xEC khoa h\u1ECDc.",
  "Pepper, you are a genius. Pepper is me.": "Pepper \u01A1i, b\u1EA1n l\xE0 thi\xEAn t\xE0i. Pepper l\xE0 m\xECnh \u0111\xF3.",
  "These will make the stew sing.": "M\u1EA5y th\u1EE9 n\xE0y s\u1EBD l\xE0m n\u1ED3i h\u1EA7m h\xE1t l\xEAn.",
  "Straight from the garden to my basket.": "T\u1EEB v\u01B0\u1EDDn th\u1EB3ng v\xE0o gi\u1ECF m\xECnh.",
  "The kitchen is going to smell amazing.": "Nh\xE0 b\u1EBFp s\u1EAFp th\u01A1m l\u1EEBng r\u1ED3i.",
  "I have got a good feeling about this dish.": "M\xECnh c\xF3 linh c\u1EA3m t\u1ED1t v\u1EC1 m\xF3n n\xE0y.",
  "Basket full. Time to stir.": "Gi\u1ECF \u0111\u1EA7y r\u1ED3i. T\u1EDBi l\xFAc khu\u1EA5y th\xF4i.",
  "Gather first, cook second, eat third.": "H\xE1i tr\u01B0\u1EDBc, n\u1EA5u sau, \u0103n cu\u1ED1i c\xF9ng.",
  "Hi boss! You look great today.": "Ch\xE0o s\u1EBFp! H\xF4m nay s\u1EBFp tr\xF4ng tuy\u1EC7t l\u1EAFm.",
  "Good to see you, boss. The garden loves you.": "Vui \u0111\u01B0\u1EE3c g\u1EB7p s\u1EBFp. V\u01B0\u1EDDn qu\xFD s\u1EBFp l\u1EAFm.",
  "You work so hard. We are proud of you.": "S\u1EBFp l\xE0m vi\u1EC7c ch\u0103m ch\u1EC9 gh\xEA. T\u1EE5i em t\u1EF1 h\xE0o v\u1EC1 s\u1EBFp.",
  "Thank you for rescuing us, boss. Best day ever.": "C\u1EA3m \u01A1n s\u1EBFp \u0111\xE3 c\u1EE9u t\u1EE5i em. Ng\xE0y tuy\u1EC7t nh\u1EA5t lu\xF4n.",
  "Everything is under control. You can relax.": "M\u1ECDi th\u1EE9 \u0111\u1EC1u \u1ED5n. S\u1EBFp c\u1EE9 th\u01B0 gi\xE3n \u0111i.",
  "Your boots are very shiny today.": "Gi\xE0y s\u1EBFp h\xF4m nay b\xF3ng lo\xE1ng.",
  "I saved you the best one. Do not tell the others.": "Em \u0111\u1EC3 d\xE0nh c\xE1i ngon nh\u1EA5t cho s\u1EBFp. \u0110\u1EEBng n\xF3i v\u1EDBi m\u1EA5y b\u1EA1n kh\xE1c.",
  "You make this village feel like home.": "S\u1EBFp l\xE0m ng\xF4i l\xE0ng n\xE0y nh\u01B0 m\u1ED9t m\xE1i nh\xE0.",
  "Have you eaten? You should eat. I can cook!": "S\u1EBFp \u0103n ch\u01B0a? \u0102n \u0111i nha. Em n\u1EA5u \u0111\u01B0\u1EE3c m\xE0!",
  "Nice weather for adventures, boss.": "Th\u1EDDi ti\u1EBFt \u0111\u1EB9p cho phi\xEAu l\u01B0u qu\xE1, s\u1EBFp.",
  "I like working for you. The boss is kind.": "Em th\xEDch l\xE0m vi\u1EC7c cho s\u1EBFp. S\u1EBFp t\u1ED1t b\u1EE5ng.",
  "If you are tired, the sofa is waiting.": "S\u1EBFp m\u1EC7t th\xEC gh\u1EBF sofa \u0111ang ch\u1EDD.",
  "That is a very good hat you are wearing.": "C\xE1i n\xF3n s\u1EBFp \u0111\u1ED9i \u0111\u1EB9p l\u1EAFm.",
  "The animals asked about you. They miss your hugs.": "M\u1EA5y b\xE9 th\xFA h\u1ECFi th\u0103m s\u1EBFp. T\u1EE5i n\xF3 nh\u1EDB c\xE1i \xF4m c\u1EE7a s\u1EBFp.",
  "Smile, boss! The day is good.": "C\u01B0\u1EDDi l\xEAn s\u1EBFp! Ng\xE0y h\xF4m nay t\u1ED1t l\xE0nh.",
  "I would follow you to the moon. Bring snacks though.": "Em theo s\u1EBFp t\u1EDBi t\u1EADn m\u1EB7t tr\u0103ng. Nh\u1EDB mang \u0111\u1ED3 \u0103n v\u1EB7t nha.",
  "You are the best explorer in the whole world.": "S\u1EBFp l\xE0 nh\xE0 th\xE1m hi\u1EC3m gi\u1ECFi nh\u1EA5t th\u1EBF gi\u1EDBi.",
  "Take a deep breath. Smell that? That is our garden.": "H\xEDt s\xE2u n\xE0o. Ng\u1EEDi th\u1EA5y kh\xF4ng? \u0110\xF3 l\xE0 v\u01B0\u1EDDn c\u1EE7a m\xECnh.",
  "Thanks for the energy, boss. It keeps us going!": "C\u1EA3m \u01A1n s\u1EBFp v\u1EC1 n\u0103ng l\u01B0\u1EE3ng. Nh\u1EDD n\xF3 t\u1EE5i em m\u1EDBi ch\u1EA1y \u0111\u01B0\u1EE3c!",
  "We are a good team, you and me.": "M\xECnh l\xE0 m\u1ED9t \u0111\u1ED9i t\u1ED1t, s\u1EBFp v\xE0 em.",
  "Time to pop home for a moment.": "T\u1EDBi gi\u1EDD gh\xE9 nh\xE0 m\u1ED9t ch\xFAt.",
  "I will be right back. Do not miss me too much.": "Em quay l\u1EA1i li\u1EC1n. \u0110\u1EEBng nh\u1EDB em qu\xE1 nha.",
  "Home break! Feet up, nose in a cup of tea.": "Ngh\u1EC9 \u1EDF nh\xE0 th\xF4i! G\xE1c ch\xE2n, ng\u1EEDi t\xE1ch tr\xE0.",
  "Nature calls. Home calls too.": "Thi\xEAn nhi\xEAn g\u1ECDi. Nh\xE0 c\u0169ng g\u1ECDi.",
  "Just going to put these things away.": "\u0110i c\u1EA5t m\u1EA5y th\u1EE9 n\xE0y m\u1ED9t ch\xFAt.",
  "A quick rest and then back to work.": "Ngh\u1EC9 ch\xFAt x\xEDu r\u1ED3i quay l\u1EA1i l\xE0m.",
  "The kettle has been calling my name.": "C\xE1i \u1EA5m \u0111ang g\u1ECDi t\xEAn m\xECnh n\xE3y gi\u1EDD.",
  "I am off to the cottage. Save me a seat.": "M\xECnh v\u1EC1 nh\xE0 nh\u1ECF \u0111\xE2y. Gi\u1EEF ch\u1ED7 cho m\xECnh nha.",
  "Even helpers need a cosy moment.": "Ng\u01B0\u1EDDi gi\xFAp vi\u1EC7c c\u0169ng c\u1EA7n m\u1ED9t l\xFAc \u1EA5m c\xFAng.",
  "Going in to warm up by the fire.": "V\xE0o s\u01B0\u1EDFi \u1EA5m c\u1EA1nh l\xF2 th\xF4i.",
  "Back in a minute, I promise.": "M\u1ED9t ph\xFAt n\u1EEFa m\xECnh ra, h\u1EE9a \u0111\xF3.",
  "Oh, I think I left the soup on.": "\xD4i, h\xECnh nh\u01B0 m\xECnh \u0111\u1EC3 n\u1ED3i s\xFAp tr\xEAn b\u1EBFp.",
  "Home sweet home, here I come.": "Nh\xE0 l\xE0 nh\u1EA5t, m\xECnh v\u1EC1 \u0111\xE2y.",
  "Quick snack and a sit-down.": "\u0102n nh\u1EB9 m\u1ED9t ch\xFAt v\xE0 ng\u1ED3i ngh\u1EC9.",
  "Do not go anywhere without me!": "\u0110\u1EEBng \u0111i \u0111\xE2u m\xE0 kh\xF4ng c\xF3 m\xECnh nha!",
  "I will freshen up and be right out.": "M\xECnh ch\u1EC9nh trang ch\xFAt r\u1ED3i ra li\u1EC1n.",
  "The cottage looks so inviting from here.": "T\u1EEB \u0111\xE2y ng\xF4i nh\xE0 tr\xF4ng h\u1EA5p d\u1EABn gh\xEA.",
  "Break time! The best part of any job.": "Gi\u1EDD ngh\u1EC9! Ph\u1EA7n hay nh\u1EA5t c\u1EE7a m\u1ECDi c\xF4ng vi\u1EC7c.",
  "I need a minute with the sofa.": "M\xECnh c\u1EA7n m\u1ED9t ph\xFAt v\u1EDBi c\xE1i sofa.",
  "See you soon, garden!": "H\u1EB9n g\u1EB7p l\u1EA1i, khu v\u01B0\u1EDDn!",
  "New clothes, new me!": "Qu\u1EA7n \xE1o m\u1EDBi, m\xECnh m\u1EDBi!",
  "Ta-da! What do you think of this one?": "Tada! B\u1ED9 n\xE0y sao n\xE8?",
  "I tried on everything. This is the winner.": "M\xECnh th\u1EED h\u1EBFt r\u1ED3i. B\u1ED9 n\xE0y th\u1EAFng.",
  "A fresh outfit for fresh work.": "\u0110\u1ED3 m\u1EDBi cho vi\u1EC7c m\u1EDBi.",
  "Do I look fancy? I feel fancy.": "M\xECnh tr\xF4ng sang kh\xF4ng? M\xECnh th\u1EA5y sang l\u1EAFm.",
  "The mirror said yes. The mirror is never wrong.": "G\u01B0\u01A1ng n\xF3i \u0111\u01B0\u1EE3c. G\u01B0\u01A1ng kh\xF4ng bao gi\u1EDD sai.",
  "Clean, fresh and ready to cook.": "S\u1EA1ch s\u1EBD, t\u01B0\u01A1i m\u1EDBi, s\u1EB5n s\xE0ng n\u1EA5u.",
  "That old outfit was getting tired.": "B\u1ED9 c\u0169 m\u1EC7t r\u1ED3i.",
  "Everything goes with a good attitude.": "C\xE1i g\xEC c\u0169ng h\u1EE3p n\u1EBFu c\xF3 th\xE1i \u0111\u1ED9 t\u1ED1t.",
  "A hat makes a day.": "M\u1ED9t c\xE1i n\xF3n l\xE0m n\xEAn m\u1ED9t ng\xE0y.",
  "Do not tell the soup I changed.": "\u0110\u1EEBng n\xF3i v\u1EDBi n\u1ED3i s\xFAp l\xE0 m\xECnh \u0111\xE3 thay \u0111\u1ED3.",
  "Boss, your wardrobe is amazing!": "S\u1EBFp \u01A1i, t\u1EE7 \u0111\u1ED3 c\u1EE7a s\u1EBFp tuy\u1EC7t qu\xE1!"
};

