  "Took {count} items from the chest.": "\u0110\xE3 l\u1EA5y {count} m\xF3n t\u1EEB r\u01B0\u01A1ng.",
  "{count} from the chest": "{count} m\xF3n t\u1EEB r\u01B0\u01A1ng",
  // The 24-bed cap trim of older saves.
  "Your garden now holds {max} beds: {beds} extra beds were refunded for \u03DF {energy}.": "Khu v\u01B0\u1EDDn gi\u1EDD c\xF3 {max} lu\u1ED1ng: {beds} lu\u1ED1ng th\u1EEBa \u0111\xE3 \u0111\u01B0\u1EE3c ho\xE0n \u03DF {energy}.",
  "Their crops are in your bag.": "C\xE2y tr\u1ED3ng tr\xEAn c\xE1c lu\u1ED1ng \u0111\xF3 \u0111\xE3 v\xE0o ba l\xF4 c\u1EE7a b\u1EA1n.",
  // Bed upgrades.
  "Bed level {level} of {max}": "Lu\u1ED1ng c\u1EA5p {level}/{max}",
